/* Banco de preguntas. `a` es el indice de la opcion correcta empezando en 0. */
export const QUESTIONS = [
  // --- PHY ---
  { id: 1, dom: "phy", q: "¿Qué técnica de modulación emplea LoRa en la capa física?",
    opts: ["FSK de banda estrecha", "OFDM de 64 portadoras", "DSSS con códigos Gold", "Chirp Spread Spectrum (CSS)"], a: 3,
    exp: "LoRa usa Chirp Spread Spectrum: la portadora barre linealmente un rango de frecuencia (chirp). Da alta inmunidad al ruido y al efecto Doppler, y permite demodular por debajo del nivel de ruido. LoRaWAN también admite GFSK en algunos data rates (DR7 en EU868)." },
  { id: 2, dom: "phy", q: "Si el Spreading Factor pasa de SF7 a SF8 manteniendo el ancho de banda, ¿qué ocurre con la duración de símbolo?",
    opts: ["Se reduce a la mitad", "No cambia", "Se duplica", "Se multiplica por cuatro"], a: 2,
    exp: "Tsym = 2^SF / BW. Cada incremento de SF duplica la duración del símbolo, así que duplica aproximadamente el tiempo en aire y reduce a la mitad la tasa binaria, a cambio de unos ~2,5 dB más de sensibilidad." },
  { id: 3, dom: "phy", q: "¿Cuál es la duración de símbolo con SF12 y BW = 125 kHz?",
    opts: ["8,192 ms", "4,096 ms", "1,024 ms", "32,768 ms"], a: 3,
    exp: "Tsym = 2^12 / 125000 = 4096 / 125000 = 32,768 ms. Es el símbolo más largo de LoRaWAN clásico y la razón de que SF12 tenga tiempos en aire de varios segundos." },
  { id: 4, dom: "phy", q: "¿Por qué se activa el Low Data Rate Optimization (LDRO) en SF11 y SF12 con BW 125 kHz?",
    opts: ["Para aumentar la potencia de transmisión", "Para compensar la deriva de reloj durante símbolos muy largos", "Para reducir el consumo del PA", "Para permitir el uso de CR 4/8"], a: 1,
    exp: "Con símbolos de decenas de milisegundos, la deriva del oscilador puede desalinear la demodulación. El LDRO elimina 2 bits por símbolo (DE=1 en la fórmula de ToA) para dar margen, a costa de reducir la tasa efectiva." },
  { id: 5, dom: "phy", q: "Dos nodos transmiten a la vez en la misma frecuencia con SF7 y SF10. ¿Qué es lo más probable?",
    opts: ["Colisionan y se pierden ambos paquetes", "El gateway conmuta al SF más alto y descarta el resto", "Solo se recibe el de SF7 siempre", "El gateway puede demodular ambos gracias a la cuasi-ortogonalidad de los SF"], a: 3,
    exp: "Los spreading factors son cuasi-ortogonales: un gateway multicanal con demoduladores paralelos puede recibir simultáneamente señales con SF distintos en el mismo canal, siempre que la diferencia de potencia recibida no supere el margen de rechazo de co-canal." },
  { id: 6, dom: "phy", q: "¿Qué representa el Coding Rate 4/5 en LoRa?",
    opts: ["Un bit de redundancia por cada 4 bits útiles", "Cuatro de cada cinco paquetes llevan CRC", "La relación entre BW y SF", "El ratio de duty cycle permitido"], a: 0, ref: "RP002 §4.1.2",
    exp: "El CR indica la corrección de errores hacia delante (FEC) tipo Hamming: 4/5 añade 1 bit de paridad por cada 4 de datos; 4/8 añade 4. Más redundancia mejora la robustez pero alarga el tiempo en aire." },
  { id: 7, dom: "phy", q: "Orden aproximado de sensibilidad del receptor para SF12/BW125 en un transceptor típico:",
    opts: ["−98 dBm", "−110 dBm", "−123 dBm", "−137 dBm"], a: 3,
    exp: "SF7/125 kHz ronda −123 dBm y SF12/125 kHz llega a unos −137 dBm. Ese margen extra de ~14 dB es la ganancia de proceso que da a LoRa su alcance kilométrico." },
  { id: 8, dom: "phy", q: "En la fórmula de tiempo en aire, ¿cuántos símbolos aporta el preámbulo estándar de LoRaWAN?",
    opts: ["8 símbolos exactos", "12,25 símbolos", "8 + 4,25 símbolos", "6 símbolos"], a: 2, ref: "RP002 §4.1.1",
    exp: "LoRaWAN fija n_preamble = 8, y la fórmula suma 4,25 símbolos correspondientes a los chirps de sincronización invertidos: Tpreamble = (8 + 4,25) · Tsym." },
  { id: 9, dom: "phy", q: "¿Qué efecto tiene duplicar el ancho de banda de 125 a 250 kHz manteniendo el SF?",
    opts: ["Duplica el alcance", "Duplica la tasa binaria y reduce ~3 dB la sensibilidad", "No afecta a la sensibilidad", "Reduce a la mitad el consumo"], a: 1,
    exp: "Al duplicar BW, Tsym se reduce a la mitad: el doble de tasa y la mitad de tiempo en aire, pero entra el doble de potencia de ruido, lo que degrada la sensibilidad en unos 3 dB." },
  { id: 10, dom: "phy", q: "LR-FHSS se introduce en LoRaWAN principalmente para:",
    opts: ["Mejorar la capacidad en redes muy densas y el enlace directo a satélite", "Aumentar la carga útil máxima", "Sustituir a GFSK en downlink", "Habilitar la clase B sin baliza"], a: 0, ref: "RP002 §4.3",
    exp: "LR-FHSS (Long Range Frequency Hopping Spread Spectrum) se usa en uplink, aparece en data rates altos de los parámetros regionales y mejora la robustez y capacidad en despliegues densos, además de habilitar recepción por satélites LEO." },
  { id: 11, dom: "phy", q: "¿Cuál es el impacto de un SF más alto sobre el consumo energético del nodo por mensaje?",
    opts: ["Lo reduce, porque se transmite con menos potencia", "Lo aumenta, porque el transmisor está activo mucho más tiempo", "No influye", "Depende solo del coding rate"], a: 1,
    exp: "La energía por mensaje es potencia × tiempo. Subir de SF7 a SF12 puede multiplicar por más de 30 el tiempo en aire, así que el ADR bajando el SF es la palanca principal de vida de batería." },
  { id: 12, dom: "phy", q: "El campo Sync Word en LoRa sirve para:",
    opts: ["Separar redes que comparten frecuencia y SF", "Cifrar la cabecera física", "Sincronizar el reloj de baliza", "Indicar el coding rate"], a: 0, ref: "RP002 §4.1.2",
    exp: "El Sync Word (0x34 para redes públicas LoRaWAN, 0x12 típicamente para privadas) hace que un receptor descarte tempranamente los paquetes de otra red aunque coincidan frecuencia y SF. No aporta seguridad." },

  // --- ARQ ---
  { id: 13, dom: "arq", q: "La topología de una red LoRaWAN se describe como:",
    opts: ["Estrella de estrellas", "Malla con encaminamiento entre nodos", "Anillo redundante", "Árbol jerárquico con repetidores"], a: 0, ref: "TS002 §3",
    exp: "Los dispositivos hablan con todos los gateways a su alcance (estrella) y los gateways se conectan al Network Server (segunda estrella). No hay malla: los nodos no reenvían tráfico ajeno, lo que preserva la batería." },
  { id: 14, dom: "arq", q: "¿Qué papel cumple el gateway en LoRaWAN?",
    opts: ["Descifra la carga útil de aplicación antes de reenviarla", "Decide qué dispositivos pueden unirse a la red", "Actúa como puente transparente que reenvía las tramas con metadatos de radio", "Genera las claves de sesión"], a: 2, ref: "TS002 §3",
    exp: "El gateway es un puente sin estado: no descifra nada ni está asociado a dispositivos concretos. Añade metadatos (RSSI, SNR, marca de tiempo, canal) y entrega la trama al Network Server, que decide y deduplica." },
  { id: 15, dom: "arq", q: "¿Quién elimina los duplicados cuando varios gateways reciben el mismo uplink?",
    opts: ["El Join Server", "El propio gateway mediante CAD", "El Application Server", "El Network Server"], a: 3, ref: "TS002 §3",
    exp: "La deduplicación es función del Network Server, que además elige el gateway con mejor SNR/RSSI para enviar el downlink correspondiente." },
  { id: 16, dom: "arq", q: "El Join Server tiene como responsabilidad principal:",
    opts: ["Almacenar la clave raíz y procesar la petición de unión, derivando las claves de sesión", "Encaminar la carga útil al cliente final", "Programar las ventanas de recepción", "Asignar canales de radio"], a: 0, ref: "TS002 §3",
    exp: "El Join Server custodia NwkKey/AppKey (o AppKey en 1.0.x), valida el MIC del Join-Request, genera el Join-Accept y entrega la clave de red al NS y la AppSKey al AS. Puede ser una entidad separada del operador de red." },
  { id: 17, dom: "arq", q: "¿Qué distingue el roaming pasivo del roaming con handover?",
    opts: ["El pasivo solo funciona en clase C", "En el pasivo el NS servidor solo reenvía tramas y el control MAC lo mantiene el NS doméstico", "El handover no requiere acuerdo comercial", "El pasivo cambia la DevAddr del dispositivo"], a: 1, ref: "TS002 §11.3-11.4",
    exp: "En roaming pasivo, el fNS visitado actúa de mero reenviador y el hNS conserva la sesión y el control MAC. En handover roaming, el sNS visitado asume la gestión MAC de la sesión, con un reparto de funciones más profundo." },
  { id: 18, dom: "arq", q: "El NetID se utiliza para:",
    opts: ["Identificar la red y encaminar el tráfico entre operadores", "Identificar unívocamente al dispositivo", "Cifrar el Join-Accept", "Numerar las tramas"], a: 0, ref: "TS002 §14",
    exp: "El NetID lo asigna la LoRa Alliance a cada operador; sus bits menos significativos forman el prefijo NwkID de la DevAddr, lo que permite a un NS visitado saber a qué red doméstica reenviar la trama." },
  { id: 19, dom: "arq", q: "¿Qué protocolo describe la especificación LoRaWAN Backend Interfaces?",
    opts: ["El interfaz radio entre nodo y gateway", "La mensajería entre NS, JS y AS (y entre operadores)", "El formato de payload de aplicación", "La sincronización de balizas"], a: 1, ref: "TS002 §1",
    exp: "Backend Interfaces (TS002) define mensajes HTTP/JSON como JoinReq, AppSKeyReq, PRStartReq o XmitDataReq entre los servidores. No toca la interfaz radio." },
  { id: 20, dom: "arq", q: "En una red LoRaWAN, la seguridad de la carga útil de aplicación frente al operador de red se consigue porque:",
    opts: ["El NS no dispone de la AppSKey", "El gateway cifra el tráfico con TLS", "El AS reenvía por VPN", "La DevAddr se rota en cada trama"], a: 0, ref: "TS002 §3",
    exp: "LoRaWAN aplica seguridad de extremo a extremo en dos niveles: la NwkSKey protege la integridad hacia el NS y la AppSKey cifra el FRMPayload hacia el AS. Si el AppSKey no se comparte con el operador, este no ve los datos." },
  { id: 21, dom: "arq", q: "Un Relay en LoRaWAN sirve para:",
    opts: ["Crear una malla entre dispositivos finales", "Extender cobertura reenviando tramas de nodos sin alcance directo al gateway", "Sustituir al Network Server en sitios aislados", "Aumentar el duty cycle permitido"], a: 1,
    exp: "El relé es un dispositivo alimentado que reenvía uplinks y downlinks de nodos en zonas de sombra (sótanos, interiores profundos). No convierte la red en malla: sigue habiendo un único salto adicional controlado." },

  // --- CLS ---
  { id: 22, dom: "cls", q: "¿Cuándo abre un dispositivo de clase A sus ventanas de recepción?",
    opts: ["De forma continua", "Solo tras cada transmisión de uplink", "Cada 128 segundos tras la baliza", "Cuando el NS envía un aviso"], a: 1, ref: "TS001 §2.1",
    exp: "La clase A es la base obligatoria: tras cada uplink abre RX1 y, si no recibe nada, RX2. Fuera de esas ventanas la radio está apagada, lo que da el mínimo consumo pero impide downlinks a demanda." },
  { id: 23, dom: "cls", q: "En EU868, ¿cuáles son los valores por defecto de RECEIVE_DELAY1 y RECEIVE_DELAY2?",
    opts: ["1 s y 2 s", "5 s y 6 s", "2 s y 4 s", "0,5 s y 1 s"], a: 0, ref: "TS001 §3.3",
    exp: "RX1 se abre 1 s después del fin del uplink y RX2 exactamente 1 s más tarde (RECEIVE_DELAY2 = RECEIVE_DELAY1 + 1 s). Para el Join-Accept se usan JOIN_ACCEPT_DELAY1 = 5 s y DELAY2 = 6 s." },
  { id: 24, dom: "cls", q: "Por defecto, RX1 en EU868 utiliza:",
    opts: ["El mismo canal del uplink y el mismo data rate (con RX1DROffset 0)", "Siempre 869,525 MHz y DR0", "Un canal aleatorio de los tres por defecto", "El canal de baliza"], a: 0, ref: "RP002 §2.4.7",
    exp: "RX1 reutiliza la frecuencia del uplink y deriva el DR aplicando RX1DROffset (0 por defecto en EU868, es decir, mismo DR). RX2 usa parámetros fijos: 869,525 MHz y DR0 por defecto." },
  { id: 25, dom: "cls", q: "¿Qué añade la clase B sobre la clase A?",
    opts: ["Ventanas de recepción programadas (ping slots) sincronizadas por baliza", "Recepción continua", "Mayor potencia de transmisión", "Cifrado adicional del FRMPayload"], a: 0, ref: "TS001 §8.1",
    exp: "La clase B sincroniza el nodo con balizas emitidas por los gateways cada 128 s y abre ping slots periódicos. Permite latencia de downlink acotada con un consumo intermedio entre A y C." },
  { id: 26, dom: "cls", q: "El periodo de baliza en clase B es de:",
    opts: ["30 s", "64 s", "128 s", "256 s"], a: 2, ref: "TS001 §11.1",
    exp: "El intervalo de baliza es de 128 s, dividido en ventana reservada, ventana de baliza y guarda. Dentro de cada periodo el nodo abre entre 1 y 128 ping slots según la periodicidad negociada (2^(7−k))." },
  { id: 27, dom: "cls", q: "Un dispositivo de clase C:",
    opts: ["Escucha en RX2 continuamente salvo cuando transmite o está en RX1", "Solo escucha tras cada uplink", "No necesita abrir RX1", "Requiere balizas para funcionar"], a: 0, ref: "TS001 §15",
    exp: "La clase C mantiene abierta la ventana RXC (parámetros de RX2) de forma permanente, cerrándola únicamente durante la transmisión y durante RX1. Latencia mínima, pero consumo incompatible con pilas pequeñas." },
  { id: 28, dom: "cls", q: "¿Qué clase debe soportar obligatoriamente todo dispositivo LoRaWAN?",
    opts: ["Clase A", "Clase B", "Clase C", "Clases A y C"], a: 0, ref: "TS001 §2.1",
    exp: "La clase A es el modo base obligatorio. B y C son extensiones opcionales, y un dispositivo puede conmutar temporalmente a clase C (por ejemplo, durante una campaña FUOTA) y volver a A." },
  { id: 29, dom: "cls", q: "Si un nodo de clase B pierde la sincronización de baliza durante más de dos horas:",
    opts: ["Se desconecta de la red", "Cambia automáticamente a clase C", "Pasa a modo minimalista y finalmente vuelve a clase A", "Reinicia la unión OTAA"], a: 2, ref: "TS001 §10.1",
    exp: "Tras perder la baliza el nodo entra en modo beaconless, ampliando progresivamente la ventana de sus ping slots para absorber la deriva de reloj. Agotado ese periodo (unas 2 horas), abandona la clase B y avisa al servidor." },

  // --- SEC ---
  { id: 30, dom: "sec", q: "¿Qué diferencia esencial hay entre OTAA y ABP?",
    opts: ["ABP es más seguro por no intercambiar mensajes", "ABP no usa cifrado", "OTAA solo funciona en clase C", "OTAA negocia dinámicamente DevAddr y claves de sesión en cada unión"], a: 3, ref: "TS001 §6",
    exp: "En OTAA el dispositivo ejecuta el procedimiento de join y obtiene DevAddr y claves de sesión frescas. En ABP están grabadas de fábrica y no cambian nunca, lo que dificulta la rotación de claves y la gestión de contadores." },
  { id: 31, dom: "sec", q: "¿Cuántos bytes ocupa el MIC de una trama LoRaWAN y con qué algoritmo se calcula?",
    opts: ["2 bytes, CRC-16", "4 bytes, AES-128 CMAC", "8 bytes, HMAC-SHA256", "4 bytes, CRC-32"], a: 1, ref: "TS001 §4.4",
    exp: "El Message Integrity Code son 4 bytes obtenidos con AES-128 en modo CMAC sobre la trama completa. El cifrado del payload usa AES-128 en modo CTR, con claves distintas." },
  { id: 32, dom: "sec", q: "En LoRaWAN 1.0.x, ¿qué claves de sesión se derivan de la AppKey durante el join?",
    opts: ["NwkSKey y AppSKey", "FNwkSIntKey y SNwkSIntKey", "NwkSEncKey y JSIntKey", "Solo la AppSKey"], a: 0, ref: "TS001 §6.2.6",
    exp: "En 1.0.x la única clave raíz es la AppKey, de la que se derivan NwkSKey (integridad y comandos MAC) y AppSKey (cifrado de la carga de aplicación). En 1.1 hay dos raíces, NwkKey y AppKey, y cuatro claves de sesión." },
  { id: 33, dom: "sec", q: "¿Qué contiene un Join-Request?",
    opts: ["DevAddr, FCnt y MIC", "NetID, DevAddr y CFList", "AppKey cifrada y DevEUI", "JoinEUI, DevEUI y DevNonce"], a: 3, ref: "TS001 §6.2.5",
    exp: "El Join-Request son 18 bytes: JoinEUI (8), DevEUI (8) y DevNonce (2), más el MIC. Va sin cifrar, pero su integridad se protege con la clave raíz, de modo que solo el Join Server puede validarlo." },
  { id: 34, dom: "sec", q: "El Join-Accept se protege criptográficamente:",
    opts: ["Con la NwkSKey recién derivada", "Aplicando la operación de descifrado AES con la clave raíz, de forma que el nodo cifra para recuperarlo", "Con TLS entre gateway y nodo", "No se protege, va en claro"], a: 1, ref: "TS001 §6.2.6",
    exp: "El servidor aplica la operación de descifrado AES sobre el Join-Accept usando la clave raíz; el dispositivo lo recupera aplicando el cifrado. Así el nodo solo necesita implementar la primitiva de cifrado AES." },
  { id: 35, dom: "sec", q: "¿Qué campos opcionales puede incluir el Join-Accept además de JoinNonce, NetID, DevAddr, DLSettings y RxDelay?",
    opts: ["La AppSKey en claro", "El DevEUI del dispositivo", "La CFList de 16 bytes con canales adicionales", "La lista de gateways cercanos"], a: 2, ref: "TS001 §6.2.6",
    exp: "La CFList opcional ocupa 16 bytes y permite al servidor comunicar canales adicionales (en EU868, hasta cinco frecuencias más) o máscaras de canal según región. Sin ella el Join-Accept mide 12 bytes de payload; con ella, 28." },
  { id: 36, dom: "sec", q: "A partir de LoRaWAN 1.0.3, el DevNonce debe ser:",
    opts: ["Un valor aleatorio nuevo en cada intento", "Derivado del FCntUp", "El mismo valor grabado en fábrica", "Un contador que se incrementa monótonamente y nunca se repite"], a: 3, ref: "TS001 §6.2.5",
    exp: "El cambio de aleatorio a contador monótono evita ataques de repetición del Join-Request. El servidor rechaza cualquier DevNonce igual o inferior a uno ya visto, por lo que reiniciar ese contador en el nodo sin reiniciarlo en el servidor rompe las uniones." },
  { id: 37, dom: "sec", q: "¿Cuál es el mayor riesgo operativo del uso de ABP?",
    opts: ["Que el nodo no pueda usar ADR", "Que no admita clase A", "Que no se pueda cifrar el payload", "Que el reinicio del dispositivo reinicie los contadores de trama y el servidor descarte las tramas"], a: 3, ref: "TS001 §6.3",
    exp: "Con ABP los contadores viven en memoria no volátil; si se pierden al reiniciar, el NS los interpreta como repeticiones y descarta las tramas. Desactivar la comprobación de contador como parche abre la puerta a ataques de repetición." },
  { id: 38, dom: "sec", q: "En LoRaWAN 1.1, ¿qué clave protege la integridad de los uplinks desde la perspectiva del servidor de red servidor (serving)?",
    opts: ["AppSKey", "SNwkSIntKey", "NwkSEncKey", "JSEncKey"], a: 1, ref: "TS001-1.1 §6.1.2.3",
    exp: "1.1 divide la integridad de red: FNwkSIntKey (forwarding) y SNwkSIntKey (serving) generan un MIC de 4 bytes en dos mitades, lo que permite el roaming sin ceder el control completo. NwkSEncKey cifra los comandos MAC." },
  { id: 39, dom: "sec", q: "Un ataque de repetición sobre uplinks se previene principalmente mediante:",
    opts: ["El Sync Word", "El contador de trama FCntUp verificado por el servidor", "El CRC de la capa física", "La rotación de canal"], a: 1, ref: "TS001 §4.3.1",
    exp: "El NS mantiene el último FCntUp aceptado y descarta tramas con contador repetido o inferior. Es el motivo por el que la gestión persistente de contadores es crítica, sobre todo en ABP." },

  // --- MAC ---
  { id: 40, dom: "mac", q: "¿Cuál es el orden correcto de los campos del PHYPayload?",
    opts: ["MHDR | MACPayload | MIC", "Preámbulo | MIC | MACPayload", "MHDR | MIC | MACPayload", "FHDR | MHDR | MIC"], a: 0, ref: "TS001 §4.1",
    exp: "PHYPayload = MHDR (1 byte) + MACPayload + MIC (4 bytes). A su vez, MACPayload = FHDR + FPort (opcional) + FRMPayload (opcional)." },
  { id: 41, dom: "mac", q: "¿Qué valor de MType corresponde a un Unconfirmed Data Up?",
    opts: ["000", "110", "100", "010"], a: 3, ref: "TS001 §4.2.1",
    exp: "Los MType son: 000 Join-Request, 001 Join-Accept, 010 Unconfirmed Data Up, 011 Unconfirmed Data Down, 100 Confirmed Data Up, 101 Confirmed Data Down, 110 Rejoin-Request y 111 Proprietary." },
  { id: 42, dom: "mac", q: "El campo FPort con valor 0 indica que:",
    opts: ["La trama va vacía", "El FRMPayload contiene únicamente comandos MAC", "Se trata de tráfico de certificación", "El puerto está reservado por el fabricante"], a: 1, ref: "TS001 §4.3.2",
    exp: "FPort = 0 significa que el FRMPayload lleva comandos MAC cifrados con la clave de red. Los puertos 1–223 son de aplicación, el 224 se reserva al protocolo de pruebas de certificación y 225–255 quedan reservados." },
  { id: 43, dom: "mac", q: "¿Cuántos bytes ocupa el campo FOpts como máximo?",
    opts: ["8", "32", "16", "15"], a: 3, ref: "TS001 §4.3.1",
    exp: "FOpts admite hasta 15 bytes de comandos MAC piggyback dentro del FHDR, sin cifrar en 1.0.x. Si no caben, deben enviarse en el FRMPayload con FPort 0, y en ese caso no puede haber datos de aplicación en la misma trama." },
  { id: 44, dom: "mac", q: "El FHDR está compuesto por:",
    opts: ["DevEUI, FCnt y FCtrl", "JoinEUI, DevNonce y FCtrl", "MHDR, FPort y MIC", "DevAddr, FCtrl, FCnt y FOpts"], a: 3, ref: "TS001 §4.3.1",
    exp: "FHDR = DevAddr (4 bytes) + FCtrl (1) + FCnt (2, los 16 bits menos significativos de un contador de 32) + FOpts (0–15). El resto del contador se infiere en el servidor." },
  { id: 45, dom: "mac", q: "El bit ADR del campo FCtrl indica que:",
    opts: ["El servidor obliga a cambiar de canal", "El dispositivo permite que la red gestione su data rate y potencia", "La trama requiere confirmación", "Hay comandos MAC pendientes"], a: 1, ref: "TS001 §4.3.1",
    exp: "ADR=1 significa que el nodo delega en la red el ajuste de DR y potencia. ADRACKReq lo usa el nodo para pedir confirmación de que la red sigue oyéndolo; FPending indica al nodo que el servidor tiene más downlinks en cola." },
  { id: 46, dom: "mac", q: "El campo FCnt transmitido tiene 16 bits, pero el contador real es de 32. ¿Cómo se resuelve?",
    opts: ["El servidor reconstruye los 16 bits altos siguiendo la secuencia y detectando el desbordamiento", "El nodo envía los 16 bits altos en el FPort", "Se reinicia el contador cada 65536 tramas", "Se usan dos tramas consecutivas"], a: 0, ref: "TS001 §4.3.1",
    exp: "Solo se transmiten los 16 bits bajos para ahorrar aire; ambos extremos mantienen los 32 bits y el servidor infiere el desbordamiento. Ese contador completo entra en el cálculo del MIC y en el bloque de cifrado." },
  { id: 47, dom: "mac", q: "En una trama con datos de aplicación, ¿qué clave cifra el FRMPayload?",
    opts: ["AppSKey", "NwkSKey", "AppKey", "JSIntKey"], a: 0, ref: "TS001 §4.3.3",
    exp: "Si FPort > 0, el FRMPayload se cifra con la AppSKey. Si FPort = 0 (comandos MAC), se cifra con la NwkSKey en 1.0.x o la NwkSEncKey en 1.1." },
  { id: 48, dom: "mac", q: "Un Confirmed Data Up implica que:",
    opts: ["El servidor debe responder con un downlink que lleve el bit ACK", "El gateway envía un acuse inmediato", "La trama se retransmite tres veces siempre", "El nodo pasa a clase C"], a: 0, ref: "TS001 §4.3.1",
    exp: "El ACK viaja en el bit ACK del FCtrl de un downlink, que puede ser una trama vacía o llevar datos. Los confirmados consumen presupuesto de downlink del gateway y su uso masivo satura la capacidad de la red." },

  // --- CMD ---
  { id: 49, dom: "cmd", q: "¿Qué comando MAC usa el dispositivo para conocer la calidad del enlace y el número de gateways que lo oyen?",
    opts: ["DevStatusReq", "LinkADRReq", "LinkCheckReq", "RXParamSetupReq"], a: 2, ref: "TS001 §5.1",
    exp: "LinkCheckReq (CID 0x02) lo envía el nodo; la respuesta LinkCheckAns devuelve el margen de demodulación en dB y el número de gateways que recibieron la trama. Es la herramienta básica de diagnóstico de cobertura desde el nodo." },
  { id: 50, dom: "cmd", q: "El comando LinkADRReq permite al servidor ajustar:",
    opts: ["Solo el data rate", "Data rate, potencia de transmisión, máscara de canales y número de retransmisiones", "El periodo de baliza", "El retardo de RX1"], a: 1, ref: "TS001 §5.2",
    exp: "LinkADRReq (0x03) lleva DataRate_TXPower, ChMask, y Redundancy con ChMaskCntl y NbTrans. La respuesta confirma por separado si se aceptaron la potencia, el data rate y la máscara de canales." },
  { id: 51, dom: "cmd", q: "En EU868, los valores por defecto de ADR_ACK_LIMIT y ADR_ACK_DELAY son:",
    opts: ["32 y 16", "64 y 32", "16 y 8", "128 y 64"], a: 1, ref: "TS001 §5.2",
    exp: "Tras 64 uplinks sin downlink, el nodo activa ADRACKReq. Si en los 32 siguientes no recibe respuesta, inicia el backoff: sube la potencia al máximo, luego baja el data rate escalonadamente y finalmente restaura los canales por defecto." },
  { id: 52, dom: "cmd", q: "¿Qué comando devuelve el nivel de batería y el SNR de demodulación del dispositivo?",
    opts: ["DevStatusReq / DevStatusAns", "LinkCheckReq / Ans", "DeviceTimeReq / Ans", "DutyCycleReq"], a: 0, ref: "TS001 §5.5",
    exp: "DevStatusReq (0x06) lo inicia el servidor. La respuesta lleva un byte de batería (0 = alimentado externamente, 1–254 escala, 255 = no medible) y el margen SNR con signo de la última trama recibida." },
  { id: 53, dom: "cmd", q: "DeviceTimeReq sirve para:",
    opts: ["Sincronizar el reloj del nodo con la hora GPS de la red", "Ajustar el temporizador de RX2", "Solicitar el periodo de baliza", "Programar un downlink diferido"], a: 0, ref: "TS001 §5.9",
    exp: "DeviceTimeReq/Ans (0x0D, desde 1.0.3) devuelve la hora de la red referida a GPS. Es el mecanismo habitual para que un nodo entre en clase B o sincronice marcas temporales sin GPS propio." },
  { id: 54, dom: "cmd", q: "El comando DutyCycleReq impone:",
    opts: ["Un límite de ciclo de trabajo agregado al dispositivo", "El duty cycle regulatorio de la banda", "Un número máximo de retransmisiones", "El tiempo entre balizas"], a: 0, ref: "TS001 §5.3",
    exp: "DutyCycleReq (0x04) fija MaxDCycle, un límite agregado que el servidor impone al nodo por razones de red, adicional e independiente del límite regulatorio de cada subbanda." },
  { id: 55, dom: "cmd", q: "¿Qué ocurre si el ADR está activado en un dispositivo móvil?",
    opts: ["Funciona mejor que en uno fijo", "No tiene ningún efecto", "El servidor lo detecta y lo desactiva solo", "Puede quedarse anclado a un data rate alto y perder cobertura al desplazarse"], a: 3, ref: "TS001 §5.2",
    exp: "El ADR asume condiciones de radio estables. En dispositivos móviles la recomendación es desactivarlo y fijar un data rate conservador, o apoyarse en mecanismos de la red que reaccionen rápidamente a la pérdida de enlace." },
  { id: 56, dom: "cmd", q: "NewChannelReq permite:",
    opts: ["Definir la frecuencia y el rango de data rate de un canal adicional", "Cambiar el canal de RX2", "Añadir un gateway a la lista del nodo", "Modificar el Sync Word"], a: 0, ref: "TS001 §5.6",
    exp: "NewChannelReq (0x07) crea o borra canales de uplink indicando frecuencia y DRRange. Para modificar la frecuencia de downlink de un canal existente se usa DlChannelReq (0x0A), y RXParamSetupReq (0x05) cambia RX2 y el RX1DROffset." },
  { id: 57, dom: "cmd", q: "El parámetro NbTrans de LinkADRReq define:",
    opts: ["El número de gateways requeridos", "La cantidad de ping slots", "El número de canales activos", "Cuántas veces se repite cada uplink no confirmado"], a: 3, ref: "TS001 §5.2",
    exp: "NbTrans indica las repeticiones de cada trama de uplink para mejorar la probabilidad de recepción. Multiplica el consumo y la ocupación de espectro, así que subirlo es una decisión de compromiso." },

  // --- REG ---
  { id: 58, dom: "reg", q: "¿Cuáles son los tres canales por defecto obligatorios en EU868?",
    opts: ["868,1 / 868,3 / 868,5 MHz", "868,0 / 868,2 / 868,4 MHz", "869,4 / 869,5 / 869,6 MHz", "867,1 / 867,3 / 867,5 MHz"], a: 0, ref: "RP002 §2.4.2",
    exp: "Todo dispositivo EU868 debe implementar 868,1, 868,3 y 868,5 MHz con DR0–DR5. Los canales adicionales llegan por CFList en el Join-Accept o por NewChannelReq." },
  { id: 59, dom: "reg", q: "En EU868, ¿qué data rate corresponde a SF7 con BW 125 kHz?",
    opts: ["DR0", "DR3", "DR5", "DR6"], a: 2, ref: "RP002 §2.4.3",
    exp: "En EU868: DR0=SF12, DR1=SF11, DR2=SF10, DR3=SF9, DR4=SF8, DR5=SF7 (todos a 125 kHz), DR6=SF7/250 kHz y DR7=FSK 50 kbps." },
  { id: 60, dom: "reg", q: "Los parámetros por defecto de RX2 en EU868 son:",
    opts: ["868,5 MHz y DR5", "868,1 MHz y DR0", "867,9 MHz y DR3", "869,525 MHz y DR0"], a: 3, ref: "RP002 §2.4.7",
    exp: "RX2 usa 869,525 MHz con DR0 (SF12/125 kHz) por defecto. Esa frecuencia está en una subbanda con 10 % de ciclo de trabajo y potencia superior, pensada para downlink." },
  { id: 61, dom: "reg", q: "El límite de ciclo de trabajo del 1 % en la subbanda de 868 MHz significa que:",
    opts: ["Solo se puede usar el 1 % de los canales", "Tras transmitir 1 s hay que esperar unos 99 s en esa subbanda", "El 1 % de las tramas pueden ser confirmadas", "Se limita a 1 % la potencia radiada"], a: 1, ref: "RP002 §2.4",
    exp: "Es una restricción regulatoria por subbanda y por transmisor: el tiempo en aire acumulado no puede superar el 1 % de cada hora. Afecta también al gateway, lo que limita seriamente la capacidad de downlink." },
  { id: 62, dom: "reg", q: "En US915, el plan de canales de uplink incluye:",
    opts: ["8 canales de 125 kHz", "72 canales de 250 kHz", "16 canales de 250 kHz", "64 canales de 125 kHz más 8 de 500 kHz"], a: 3, ref: "RP002 §2.5.2",
    exp: "US915 define 64 canales de 125 kHz desde 902,3 MHz con separación de 200 kHz (DR0–DR3) y 8 canales de 500 kHz desde 903,0 MHz (DR4), más 8 canales de downlink de 500 kHz desde 923,3 MHz." },
  { id: 63, dom: "reg", q: "En US915 no hay ciclo de trabajo, pero sí:",
    opts: ["Límite de dwell time y salto de frecuencia", "Límite de tramas por día", "Prohibición de downlink", "Restricción a clase A"], a: 0, ref: "RP002 §2.5",
    exp: "La FCC exige salto de frecuencia y un tiempo máximo de permanencia por canal (dwell time de 400 ms), que en la práctica prohíbe SF12 en canales de 125 kHz y condiciona el tamaño de carga en DR0." },
  { id: 64, dom: "reg", q: "En EU868, la carga útil máxima de aplicación en DR0 es aproximadamente:",
    opts: ["11 bytes", "115 bytes", "51 bytes", "242 bytes"], a: 2, ref: "RP002 §2.4.6",
    exp: "En EU868 el valor N es 51 bytes para DR0–DR2, 115 para DR3 y 242 para DR4 y superiores. Ese margen se reduce si hay comandos MAC en FOpts, así que conviene diseñar la carga para el peor data rate." },
  { id: 65, dom: "reg", q: "El documento que define los planes de frecuencia por región se denomina:",
    opts: ["LoRaWAN Link Layer Specification", "Backend Interfaces", "Regional Parameters (RP002)", "LoRaWAN Certification Protocol"], a: 2, ref: "RP002",
    exp: "El Link Layer (TS001) define el protocolo, y Regional Parameters (RP002) especifica frecuencias, data rates, potencias, retardos y restricciones para EU868, US915, AS923, AU915, IN865, KR920, RU864, CN470 y más." },
  { id: 66, dom: "reg", q: "AS923 se caracteriza por:",
    opts: ["Un plan idéntico a EU868", "Un desplazamiento de frecuencia configurable en varios grupos (AS923-1 a -4)", "No admitir OTAA", "Trabajar en 2,4 GHz"], a: 1, ref: "RP002 §2.10",
    exp: "AS923 se define como un plan base con desplazamientos de frecuencia que generan varios grupos regionales según el país, y en algunos mercados aplica dwell time además de restricciones locales de duty cycle." },

  // --- OPS ---
  { id: 67, dom: "ops", q: "En la planificación de un despliegue, la principal ventaja de instalar la antena del gateway a mayor altura es:",
    opts: ["Reducir el consumo del gateway", "Permitir más spreading factors", "Aumentar la potencia radiada", "Ampliar el radio de la zona de Fresnel despejada y la línea de vista"], a: 3,
    exp: "La altura mejora la línea de vista y despeja la primera zona de Fresnel, que domina las pérdidas en enlaces largos. Ganar altura suele rendir más que subir la ganancia de antena, y además reduce la necesidad de SF altos." },
  { id: 68, dom: "ops", q: "En EU868 el límite habitual de potencia radiada para un dispositivo final en las bandas por defecto es:",
    opts: ["25 mW (14 dBm ERP)", "500 mW", "100 mW en todas las subbandas", "1 W"], a: 0, ref: "RP002 §2.4.3",
    exp: "Las bandas por defecto permiten 25 mW ERP, es decir 14 dBm ERP (16 dBm EIRP). Algunas subbandas, como la de 869,4–869,65 MHz usada para RX2, admiten 500 mW con 10 % de ciclo de trabajo." },
  { id: 69, dom: "ops", q: "FUOTA en LoRaWAN se apoya en un conjunto de paquetes de capa de aplicación que incluyen:",
    opts: ["Sincronización de reloj, configuración multicast y transporte fragmentado de bloques", "Un nuevo MType dedicado", "Una clase D específica", "Un canal reservado en 870 MHz"], a: 0,
    exp: "FUOTA combina Application Layer Clock Synchronization, Remote Multicast Setup, Fragmented Data Block Transport y Firmware Management, sobre puertos de aplicación reservados. La entrega suele hacerse en multicast con el nodo conmutado temporalmente a clase B o C." },
  { id: 70, dom: "ops", q: "La geolocalización por red en LoRaWAN se basa habitualmente en:",
    opts: ["TDoA usando marcas de tiempo sincronizadas por GPS en varios gateways", "Triangulación por RSSI únicamente", "El campo de posición del FHDR", "Consulta al Join Server"], a: 0, ref: "TS002 §13",
    exp: "El TDoA requiere gateways con marca de tiempo fina disciplinada por GPS y al menos tres receptores, con precisión típica de decenas a cientos de metros. El RSSI da estimaciones mucho más groseras y se usa como respaldo." },
  { id: 71, dom: "ops", q: "Un síntoma típico de saturación de la capacidad de downlink en una celda es:",
    opts: ["Aumento de las tramas confirmadas sin ACK y del ciclo de trabajo del gateway", "Aumento del SNR medio", "Descenso del número de joins", "Reducción del tiempo en aire medio"], a: 0,
    exp: "El gateway está sujeto a su propio límite de ciclo de trabajo y no puede recibir mientras transmite. Un exceso de tramas confirmadas o de comandos MAC agota ese presupuesto: se pierden ACK, el nodo retransmite y la congestión se realimenta." },
  { id: 72, dom: "ops", q: "El programa LoRaWAN Certified aporta principalmente:",
    opts: ["Verificación de que el dispositivo cumple el protocolo y los parámetros regionales", "Una garantía de cobertura", "Una licencia de uso de espectro", "La asignación del DevEUI"], a: 0,
    exp: "La certificación valida el comportamiento del dispositivo frente a la especificación y a los parámetros regionales mediante bancos de prueba autorizados. No sustituye a la certificación regulatoria (CE/RED, FCC) ni garantiza rendimiento en campo." },
  { id: 73, dom: "ops", q: "Para maximizar la vida de batería de un sensor con reporte horario, la medida más eficaz suele ser:",
    opts: ["Usar tramas confirmadas siempre", "Fijar SF12 por seguridad", "Reducir el tiempo en aire mediante ADR y cargas útiles compactas", "Aumentar NbTrans a 3"], a: 2,
    exp: "El consumo lo domina el tiempo de radio activa. Bajar el SF con ADR, comprimir la carga útil y evitar confirmaciones innecesarias reduce el tiempo en aire y, con él, la energía por mensaje y la ocupación del espectro." },
  { id: 74, dom: "ops", q: "Al dimensionar la capacidad de una celda, ¿por qué los nodos en SF12 penalizan desproporcionadamente?",
    opts: ["Consumen más canales", "Ocupan el aire decenas de veces más tiempo que los de SF7 por el mismo payload", "Exigen downlinks adicionales", "Obligan al gateway a cambiar de banda"], a: 1,
    exp: "Es el efecto de captura de aire: un mensaje en SF12 puede ocupar más de 30 veces el tiempo del mismo mensaje en SF7. Un pequeño porcentaje de nodos en el borde de cobertura puede consumir la mayor parte de la capacidad de la celda." },

  // --- PHY (ampliación) ---
  { id: 75, dom: "phy", q: "¿Qué modulación alternativa a LoRa y LR-FHSS admite LoRaWAN en algunos data rates?",
    opts: ["OFDM", "DSSS", "QPSK", "FSK (GFSK)"], a: 3, ref: "RP002 §4.2",
    exp: "El PHY de LoRaWAN define tres modulaciones: LoRa, FSK y LR-FHSS. FSK se usa típicamente en el data rate más alto de algunas regiones (DR7 en EU868)." },
  { id: 76, dom: "phy", q: "¿A qué velocidad binaria funciona el modo FSK de LoRaWAN?",
    opts: ["1200 bit/s", "9600 bit/s", "250000 bit/s", "50000 bit/s"], a: 3, ref: "RP002 §4.2.2",
    exp: "La tabla de settings de FSK fija un bitrate de 50000 bit/s, con desviación de frecuencia de 25 kHz y ancho de banda de recepción de 50 kHz." },
  { id: 77, dom: "phy", q: "En el modo FSK de LoRaWAN, la integridad del payload se protege con:",
    opts: ["Reed-Solomon", "AES-128 CMAC", "Solo whitening", "CRC-16-CCITT"], a: 3, ref: "RP002 §4.2.2",
    exp: "El CRC-16-CCITT se calcula sobre la longitud y el contenido del PHYPayload. La codificación whitening evita distribuciones de potencia no uniformes, pero no protege la integridad." },
  { id: 78, dom: "phy", q: "En regiones tipo FCC, ¿por cuántos canales físicos salta una transmisión LR-FHSS?",
    opts: ["35", "128", "86", "60"], a: 3, ref: "RP002 §4.3.1",
    exp: "En ETSI se salta entre 35 u 86 canales según el ancho de banda de salto; en FCC son 60 canales sobre una rejilla de 25,4 kHz." },
  { id: 79, dom: "phy", q: "¿Qué tasa binaria física ofrece LR-FHSS con coding rate 2/3?",
    opts: ["162 bit/s", "5470 bit/s", "325 bit/s", "980 bit/s"], a: 2, ref: "RP002 §4.3.1",
    exp: "LR-FHSS ofrece 162 bit/s con CR 1/3 y 325 bit/s con CR 2/3, muy por debajo de las tasas de LoRa clásico, a cambio de mucha más robustez en despliegues densos." },
  { id: 80, dom: "phy", q: "En la estructura física de un paquete LoRa, ¿qué va inmediatamente después del preámbulo?",
    opts: ["El CRC", "El PHDR_CRC", "El PHYPayload", "La Synchronization Word"], a: 3, ref: "RP002 §4.1.1",
    exp: "El orden es: preámbulo, Sync Word, PHDR (cabecera física), PHDR_CRC, PHYPayload y CRC (solo en uplink)." },
  { id: 81, dom: "phy", q: "Las balizas de clase B se transmiten en modo:",
    opts: ["Header explícito con CRC", "LR-FHSS", "FSK con whitening", "Header implícito, de longitud fija"], a: 3, ref: "RP002 §4.1.1",
    exp: "En modo implícito no se envían PHDR ni PHDR_CRC: todos los receptores conocen de antemano la longitud fija de la baliza." },
  { id: 82, dom: "phy", q: "¿Qué coding rate exige la conformidad LoRaWAN en el modo LoRa?",
    opts: ["4/8 fijo", "Variable según el ADR", "4/5 fijo", "Depende del ancho de banda"], a: 2, ref: "RP002 §4.1.2",
    exp: "Aunque el chip LoRa admite varios coding rates, LoRaWAN exige 4/5 fijo tanto en uplink como en downlink para ser conforme." },
  { id: 83, dom: "phy", q: "¿Cómo debe configurar un dispositivo la polaridad IQ en uplink frente al downlink?",
    opts: ["Igual en ambos sentidos", "Aleatoria", "Invertida en ambos", "No invertida en uplink, invertida en downlink"], a: 3, ref: "RP002 §4.1.2",
    exp: "Invertir la polaridad IQ del downlink evita que un nodo escuche por error las transmisiones de otros nodos como si fueran tráfico de red." },
  { id: 84, dom: "phy", q: "El 'tamaño de payload compatible con repetidor' en RP002 se define porque:",
    opts: ["Afecta solo a las balizas", "Los repetidores duplican el CRC", "Cambia el spreading factor", "Un repetidor encapsula la trama original añadiendo hasta 20 bytes de metadatos"], a: 3, ref: "RP002 §3.1",
    exp: "Para no superar el máximo de 250 bytes de MACPayload al encapsular, las tablas de payload 'repeater compatible' reservan margen para esos metadatos." },
  { id: 85, dom: "phy", q: "En LR-FHSS, ¿qué determina principalmente el tiempo en aire del payload?",
    opts: ["El spreading factor", "El número de preámbulos", "El ancho de banda de salto", "El coding rate (1/3 o 2/3) y la longitud del payload"], a: 3, ref: "RP002 §4.3.2",
    exp: "LR-FHSS no usa SF: el tiempo en aire del payload se calcula a partir del coding rate y el número de bytes, con una cabecera física repetida aparte." },
  { id: 86, dom: "phy", q: "¿Qué campo del PHDR de LoRa en modo explícito especifica, entre otras cosas, la longitud del payload?",
    opts: ["El Sync Word", "El preámbulo", "El propio PHDR, que también indica el coding rate y la presencia de CRC", "El PHYPayload"], a: 2, ref: "RP002 §4.1.1",
    exp: "El PHDR lo inserta el propio transceptor de radio, no la pila LoRaWAN, y va protegido por su propio PHDR_CRC." },
  { id: 87, dom: "phy", q: "El CRC de payload en LoRa (modo explícito) protege:",
    opts: ["Solo el downlink", "Tanto uplink como downlink por igual", "Solo el uplink; los downlinks LoRaWAN no lo llevan", "Ni uplink ni downlink"], a: 2, ref: "RP002 §4.1.1",
    exp: "Los downlinks no necesitan CRC de payload porque el propio MIC de LoRaWAN ya garantiza la integridad extremo a extremo de la trama." },
  { id: 88, dom: "phy", q: "¿Qué modulación de las que admite LoRaWAN no usa espectro ensanchado por chirp?",
    opts: ["LoRa", "LR-FHSS", "FSK (GFSK)", "Todas usan chirp"], a: 2, ref: "RP002 §4.2",
    exp: "FSK es una modulación de banda estrecha clásica; LoRa usa chirps y LR-FHSS combina espectro ensanchado con salto rápido de frecuencia." },

  // --- ARQ (ampliación) ---
  { id: 89, dom: "arq", q: "¿Qué mensaje del backend usa el Network Server para iniciar el reenvío de un uplink en itinerancia (roaming) pasiva?",
    opts: ["JoinReq", "AppSKeyReq", "PRStartReq", "RejoinReq"], a: 2, ref: "TS002 §23.2",
    exp: "PRStartReq/PRStartAns forman parte de los mensajes de Passive Roaming Start entre el fNS visitado y el sNS de origen." },
  { id: 90, dom: "arq", q: "En el modelo de referencia de red (NRM) de Backend Interfaces, ¿qué servidor conserva el Device Profile, el Service Profile y el Routing Profile?",
    opts: ["El Forwarding NS", "El Serving NS", "El Home NS", "El Visited NS"], a: 2, ref: "TS002 §3",
    exp: "El hNS es donde vive la información de aprovisionamiento del dispositivo y su relación con el Join Server; el resto de NS solo intervienen en roaming." },
  { id: 91, dom: "arq", q: "¿Qué distingue al Forwarding NS del Serving NS?",
    opts: ["El sNS no participa en roaming", "No hay diferencia, son sinónimos", "El fNS solo existe en clase B", "El fNS gestiona los gateways de radio; el sNS controla la capa MAC"], a: 3, ref: "TS002 §3",
    exp: "Cuando fNS y sNS son distintos, están en un acuerdo de roaming: el fNS reenvía tramas de sus gateways y el sNS mantiene la sesión del dispositivo." },
  { id: 92, dom: "arq", q: "El identificador único de un Network Server en Backend Interfaces es:",
    opts: ["El NetID", "El JoinEUI", "El DevAddr", "El NSID (EUI-64)"], a: 3, ref: "TS002 §3",
    exp: "Cada NS tiene un NSID propio y puede estar configurado con uno o varios NetID, que identifican a la red frente a los dispositivos." },
  { id: 93, dom: "arq", q: "¿Qué valores de NetID no requieren solicitud a la LoRa Alliance?",
    opts: ["Cualquier NetID por debajo de 0x000010", "Los NetID de tipo 7", "Todos los NetID son de uso libre", "Los valores 0x000000 y 0x000001, reservados a redes experimentales o sin roaming"], a: 3, ref: "TS002 §14",
    exp: "Fuera de esos dos valores reservados, una red que quiera hacer roaming necesita un NetID único asignado por la LoRa Alliance." },
  { id: 94, dom: "arq", q: "El campo Type del NetID (los 3 bits más significativos) determina:",
    opts: ["La versión de LoRaWAN soportada", "Si la red admite clase B", "El país de la red", "La longitud del campo ID y por tanto el tamaño de red que puede direccionar"], a: 3, ref: "TS002 §14",
    exp: "Los siete tipos de NetID reparten de forma distinta los bits entre identificador de red y margen para direcciones de dispositivo." },
  { id: 95, dom: "arq", q: "El registro que documenta la actividad de un dispositivo tras su unión en Backend Interfaces se llama:",
    opts: ["Network Traffic Record", "Session Report", "Network Activation Record", "Join Log"], a: 2, ref: "TS002 §19.1",
    exp: "El Network Activation Record se genera en la activación; el tráfico posterior se resume en el Network Traffic Record." },
  { id: 96, dom: "arq", q: "¿Qué perfil describe las capacidades del dispositivo (clase soportada, versión LoRaWAN, tipo de activación) en Backend Interfaces?",
    opts: ["Service Profile", "Routing Profile", "Device Profile", "Network Profile"], a: 2, ref: "TS002 §18.1",
    exp: "El Service Profile describe qué contrata el cliente (límites de tráfico, calidad), mientras que el Device Profile describe al propio dispositivo." },
  { id: 97, dom: "arq", q: "El Routing Profile en Backend Interfaces define principalmente:",
    opts: ["Las claves de sesión", "El plan de frecuencias regional", "Cómo encaminar los mensajes hacia el Join Server y entre servidores en roaming", "El intervalo de baliza"], a: 2, ref: "TS002 §18.3",
    exp: "Es la información de enrutado que necesita un NS para saber a qué Join Server u otro NS dirigir cada mensaje." },
  { id: 98, dom: "arq", q: "¿Cómo termina el roaming pasivo de un dispositivo según Backend Interfaces?",
    opts: ["No termina nunca de forma explícita", "Automáticamente cada 24 horas", "Con un procedimiento de Passive Roaming Stop iniciado por el fNS o el sNS", "Cuando el dispositivo cambia de clase"], a: 2, ref: "TS002 §11.3",
    exp: "Tanto el NS visitado como el de origen pueden terminar el acuerdo de roaming pasivo de forma explícita, no solo por expiración." },
  { id: 99, dom: "arq", q: "El mecanismo de 'Periodic Recovery' de Backend Interfaces se apoya en:",
    opts: ["El comando LinkCheckReq", "El Join-Request original repetido", "Reiniciar físicamente el dispositivo", "Que el dispositivo transmita periódicamente un Rejoin-Request tipo 1 por si el sNS ha perdido su estado"], a: 3, ref: "TS002 §15",
    exp: "Es la vía para recuperar la conectividad si el servidor de red pierde por completo el contexto de sesión de un dispositivo 1.1." },
  { id: 100, dom: "arq", q: "El 'Rekeying and DevAddr Reassignment' de Backend Interfaces se apoya en:",
    opts: ["El comando LinkCheckReq", "Reiniciar físicamente el dispositivo", "El Rejoin-Request tipo 2, gestionado sin desconectar al dispositivo", "El Join-Request original"], a: 2, ref: "TS002 §16",
    exp: "Permite renovar claves o reasignar la DevAddr de un dispositivo activo sin interrumpir su tráfico de aplicación." },
  { id: 101, dom: "arq", q: "La 'Key Transport Security' de Backend Interfaces se ocupa de:",
    opts: ["Autenticar al usuario final de la app", "Cifrar el FRMPayload de aplicación", "Firmar el firmware en una campaña FUOTA", "Proteger la entrega de las claves de sesión entre Join Server, Network Server y Application Server"], a: 3, ref: "TS002 §22",
    exp: "Las claves de sesión viajan entre servidores por canales que deben garantizar autenticidad, integridad y confidencialidad, no solo la radio." },
  { id: 102, dom: "arq", q: "El apartado de 'Result Codes' de Backend Interfaces define:",
    opts: ["Los códigos de clase de dispositivo", "Los códigos de región", "Los códigos de resultado que devuelven los mensajes del backend (éxito, error, etc.)", "Los códigos que forman el MIC"], a: 2, ref: "TS002 §23.5",
    exp: "Cada mensaje HTTP/JSON entre servidores puede responder con un ResultCode normalizado, además de su payload específico." },
  { id: 103, dom: "arq", q: "En Backend Interfaces, las tablas del documento son normativas; ¿qué son las figuras?",
    opts: ["También normativas", "Sustituyen a las tablas", "Aplican solo a dispositivos 1.0", "Informativas"], a: 3, ref: "TS002 §2",
    exp: "La convención del documento distingue tablas (obligatorias) de figuras (ilustrativas), como en la mayoría de especificaciones de la LoRa Alliance." },
  { id: 104, dom: "arq", q: "¿Quién negocia el acuerdo comercial y técnico que permite el roaming entre dos operadores?",
    opts: ["El propio dispositivo final", "El Join Server automáticamente", "La LoRa Alliance en cada conexión", "Se gestiona fuera de banda entre los operadores; Backend Interfaces solo define la mensajería técnica"], a: 3, ref: "TS002 §11.2",
    exp: "La especificación estandariza cómo se intercambian los mensajes de roaming, no los términos comerciales del acuerdo entre redes." },
  { id: 105, dom: "arq", q: "¿Qué implica que el enlace entre gateway y Network Server no esté cubierto por Backend Interfaces?",
    opts: ["No es posible monitorizar el gateway", "Los gateways no pueden conectarse a redes de terceros", "Cada fabricante de gateway puede usar su propio protocolo de packet forwarder", "El Network Server no puede recibir tramas"], a: 2, ref: "TS002 §1",
    exp: "Backend Interfaces estandariza NS-JS, JS-AS y NS-NS; el tramo gateway-NS queda fuera de su alcance, de ahí la variedad de packet forwarders." },

  // --- CLS (ampliación) ---
  { id: 106, dom: "cls", q: "¿Qué ocurre si un dispositivo de clase A no recibe nada en RX1 ni en RX2?",
    opts: ["Reintenta el uplink automáticamente", "Envía un Rejoin-Request", "Pasa a clase B", "Apaga la radio hasta su siguiente uplink"], a: 3, ref: "TS001 §3.3",
    exp: "La clase A no tiene downlink garantizado: si no llega nada en ninguna de las dos ventanas, el nodo vuelve a dormir." },
  { id: 107, dom: "cls", q: "En clase B, si el nodo recibe una trama durante su ping slot:",
    opts: ["Deja de escuchar el siguiente ping slot", "Se desconecta de la red", "Puede procesar downlink unicast o multicast igual que en RX1", "Cambia automáticamente a clase C"], a: 2, ref: "TS001 §9",
    exp: "El ping slot funciona como una ventana de recepción más: admite tanto tramas unicast como multicast, con sus propios formatos." },
  { id: 108, dom: "cls", q: "El bit classB del FCtrl en un uplink indica:",
    opts: ["Que hay comandos MAC pendientes", "Que la trama es confirmada", "Que el nodo soporta clase B y puede recibir ping slots", "Que se ha perdido la baliza"], a: 2, ref: "TS001 §4.3.1",
    exp: "Es el mismo bit que en clase A se usa como ADR: en uplinks de clase B se reinterpreta para señalar la disponibilidad de ping slots." },
  { id: 109, dom: "cls", q: "¿Qué mecanismo evita que dos gateways emitan la misma baliza en instantes distintos?",
    opts: ["Solo un gateway por celda puede emitir balizas", "El Network Server retrasa a uno de los dos", "Sincronización GPS de los gateways a una referencia temporal común", "No hace falta, las balizas no colisionan"], a: 2, ref: "TS001 §13.5",
    exp: "La precisión de la baliza depende de que todos los gateways de la red compartan la misma referencia temporal, típicamente GPS." },
  { id: 110, dom: "cls", q: "En clase B, el bit FPending de un downlink de ping slot indica que:",
    opts: ["El nodo debe reintentar el uplink", "La baliza se ha perdido", "El servidor tiene más datos pendientes tras este ping slot", "El ping slot ha caducado"], a: 2, ref: "TS001 §9.3",
    exp: "Avisa al nodo de que convendría abrir más ping slots o esperar al siguiente para recoger el resto de la cola de downlinks." },
  { id: 111, dom: "cls", q: "En clase C, ¿qué ventana sustituye a RX2 cuando el nodo no está transmitiendo ni en RX1?",
    opts: ["RX1 de forma permanente", "Una ventana RX3 exclusiva de clase C", "Ninguna, clase C no añade ventanas", "RXC, con los mismos parámetros que RX2"], a: 3, ref: "TS001 §15",
    exp: "RXC reutiliza la configuración de RX2 pero se mantiene abierta de forma continua, salvo durante la transmisión y durante RX1." },
  { id: 112, dom: "cls", q: "¿Qué comando MAC anuncia al servidor un cambio temporal de clase, por ejemplo durante una campaña FUOTA?",
    opts: ["ClassCReq", "ClassSwitchReq", "DeviceModeInd / DeviceModeConf", "FUOTAModeReq"], a: 2,
    exp: "Es el comando específico de clase C que permite al dispositivo avisar de que ha cambiado de clase temporalmente y confirmar la vuelta atrás." },
  { id: 113, dom: "cls", q: "¿En qué franjas divide el periodo de baliza de 128 s de la clase B?",
    opts: ["Uplink y downlink a partes iguales", "Solo ping slots consecutivos", "Ventana reservada, ventana de baliza y guarda", "RX1 y RX2"], a: 2, ref: "TS001 §11.1",
    exp: "La ventana reservada precede a la emisión de la baliza y la guarda absorbe pequeñas derivas de temporización antes del siguiente periodo." },
  { id: 114, dom: "cls", q: "El campo GwSpecific de la trama de baliza puede contener:",
    opts: ["El plan de canales completo", "La clave AppSKey", "El listado de dispositivos activos en la celda", "Coordenadas GPS del gateway, o su NetID y GatewayID"], a: 3, ref: "TS001 §13.3",
    exp: "Es información específica del gateway emisor, útil por ejemplo para que el dispositivo estime su propia posición." },

  // --- SEC (ampliación) ---
  { id: 115, dom: "sec", q: "¿De qué clave raíz se derivan JSIntKey y JSEncKey?",
    opts: ["AppKey", "NwkSEncKey", "AppSKey", "NwkKey"], a: 3, ref: "TS001-1.1 §6.1.1.4",
    exp: "Ambas son claves de por vida derivadas del NwkKey mediante AES-128, específicas para proteger el proceso de rejoin, no la sesión de datos." },
  { id: 116, dom: "sec", q: "¿Para qué se usa específicamente JSIntKey?",
    opts: ["Cifrar el FRMPayload de aplicación", "Sincronizar el reloj de clase B", "Derivar la AppSKey", "Calcular el MIC de los Rejoin-Request tipo 1 y de los Join-Accept que responden a un rejoin"], a: 3, ref: "TS001-1.1 §6.1.1.4",
    exp: "Solo el Join Server conoce JSIntKey, lo que garantiza que únicamente él puede validar un Rejoin-Request tipo 1." },
  { id: 117, dom: "sec", q: "¿Para qué se usa JSEncKey?",
    opts: ["Derivar la DevAddr", "Firmar el Join-Request inicial", "Cifrar el campo FOpts", "Cifrar el Join-Accept que responde a un Rejoin-Request"], a: 3, ref: "TS001-1.1 §6.1.1.4",
    exp: "Un Join-Accept disparado por un Join-Request normal se cifra con NwkKey; uno disparado por un rejoin se cifra con JSEncKey." },
  { id: 118, dom: "sec", q: "En LoRaWAN 1.1, cuando el bit OptNeg del Join-Accept está a 0, el dispositivo debe:",
    opts: ["Rechazar la unión", "Enviar de inmediato un Rejoin-Request tipo 1", "Usar NwkKey y AppKey por separado igualmente", "Revertir a un único conjunto de claves derivadas de NwkKey, como en 1.0"], a: 3, ref: "TS001-1.1 §6.2.3",
    exp: "Es el mecanismo de compatibilidad con Network Servers 1.0: FNwkSIntKey, SNwkSIntKey y NwkSEncKey se igualan a un único valor." },
  { id: 119, dom: "sec", q: "¿Qué distingue al contador NFCntDown del AFCntDown en LoRaWAN 1.1?",
    opts: ["NFCntDown se usa solo en uplink", "Son sinónimos del mismo contador", "NFCntDown cuenta downlinks de comandos MAC (puerto 0); AFCntDown cuenta downlinks de aplicación", "AFCntDown solo existe en clase B"], a: 2, ref: "TS001-1.1 §6.1.2.6",
    exp: "Separar ambos contadores permite que la sesión de red y la de aplicación evolucionen de forma independiente, alineado con el resto de la separación de 1.1." },
  { id: 120, dom: "sec", q: "¿Qué sustituye en LoRaWAN 1.1 al único FCntDwn que existía en 1.0?",
    opts: ["Se mantiene igual, no cambia", "Se fusiona con el FCntUp", "Se elimina, ya no hay contador de downlink", "Se desdobla en NFCntDown y AFCntDown, uno por sesión de red y otro por sesión de aplicación"], a: 3, ref: "TS001-1.1 §6.1.2.6",
    exp: "Es consecuencia directa de separar la sesión de red (NS) de la de aplicación (AS) en el modelo de claves de 1.1." },
  { id: 121, dom: "sec", q: "Un Rejoin-Request tipo 0 sirve para:",
    opts: ["Restaurar una sesión perdida consultando al Join Server", "Cambiar solo la DevAddr sin tocar las claves", "Reiniciar completamente el contexto del dispositivo (DevAddr, claves de sesión y parámetros de radio) sin pasar por el Join Server", "Sincronizar el reloj de clase B"], a: 2, ref: "TS001-1.1 §6.2.4",
    exp: "Solo puede verificarlo el Network Server sirviente u origen, nunca se enruta al Join Server, a diferencia del tipo 1." },
  { id: 122, dom: "sec", q: "Un Rejoin-Request tipo 1 se diferencia del tipo 0 en que:",
    opts: ["No lleva contador anti-repetición", "Solo puede transmitirlo un dispositivo ABP", "Contiene JoinEUI y DevEUI, y solo el Join Server puede verificar su MIC", "Cambia la clase del dispositivo"], a: 2, ref: "TS001-1.1 §6.2.4.2",
    exp: "Se enruta igual que un Join-Request original: cualquier Network Server que lo reciba lo reenvía al Join Server correspondiente." },
  { id: 123, dom: "sec", q: "Un Rejoin-Request tipo 2 permite:",
    opts: ["Solicitar un nuevo Join Server", "Restaurar un DevEUI perdido", "Rekeying o cambio de DevAddr manteniendo los parámetros de radio sin cambios", "Cambiar el plan regional del dispositivo"], a: 2, ref: "TS001-1.1 §6.2.4",
    exp: "A diferencia del tipo 0, el tipo 2 no toca la configuración de radio del dispositivo, solo las claves y opcionalmente la DevAddr." },
  { id: 124, dom: "sec", q: "El contador RJcount0, usado en los Rejoin-Request tipo 0 y 2, se reinicia a cero:",
    opts: ["Cada 24 horas", "Nunca", "Cada vez que se procesa con éxito un Join-Accept", "Al cambiar de clase"], a: 2, ref: "TS001-1.1 §6.2.4.1",
    exp: "Es un contador de 16 bits que nunca debe dar la vuelta: si llega a 2^16−1, el dispositivo debe dejar de transmitir ese tipo de rejoin." },
  { id: 125, dom: "sec", q: "¿Qué clave se usa para calcular el MIC de un Rejoin-Request tipo 0 o 2?",
    opts: ["NwkKey", "JSIntKey", "SNwkSIntKey", "AppSKey"], a: 2, ref: "TS001-1.1 §6.2.4.1",
    exp: "A diferencia del tipo 1, que usa JSIntKey, los tipos 0 y 2 los verifica el Network Server con la clave de sesión SNwkSIntKey ya establecida." },
  { id: 126, dom: "sec", q: "El comando ForceRejoinReq permite al servidor:",
    opts: ["Bloquear el uplink durante un tiempo fijo", "Expulsar al dispositivo de la red de forma permanente", "Cambiar el DevEUI del dispositivo", "Forzar al dispositivo a transmitir de inmediato un Rejoin-Request tipo 0 o 2, con periodicidad y reintentos programables"], a: 3, ref: "TS001-1.1 §5.13",
    exp: "Es la vía para que la red inicie de forma proactiva un rekeying o un handover de roaming, en vez de esperar a que el dispositivo lo haga por sí mismo." },
  { id: 127, dom: "sec", q: "El comando ResetInd/ResetConf de LoRaWAN 1.1 está pensado para:",
    opts: ["Cualquier dispositivo, tanto OTAA como ABP", "Dispositivos ABP que han perdido su contexto MAC en RAM tras un reinicio, sin resetear los contadores de trama", "Forzar un nuevo Join-Request", "Sincronizar el reloj tras salir de clase B"], a: 1, ref: "TS001-1.1 §5.1",
    exp: "Los dispositivos OTA no deben implementarlo nunca: su contexto se restablece de forma natural mediante el procedimiento de unión." },
  { id: 128, dom: "sec", q: "¿Qué NO se reinicia con el comando ResetInd de un dispositivo ABP?",
    opts: ["Los parámetros de radio por defecto", "Los contadores de trama (uplink y downlink), que nunca se resetean en ABP", "El contexto MAC en RAM", "Nada, todo se reinicia"], a: 1, ref: "TS001-1.1 §5.1",
    exp: "Es la garantía frente a repetición: aunque el dispositivo pierda su estado en RAM, los contadores persistentes en memoria no volátil siguen protegiendo la sesión." },
  { id: 129, dom: "sec", q: "El comando RekeyInd que envía el dispositivo tras un Join-Accept exitoso sirve para:",
    opts: ["Pedir una nueva clave raíz", "Confirmar al servidor que ya usa el nuevo contexto de seguridad, para que pueda descartar el anterior", "Solicitar un cambio de clase", "Cancelar la unión en curso"], a: 1, ref: "TS001-1.1 §6.2.3",
    exp: "Hasta que no llega un uplink con RekeyInd, el servidor mantiene vivos tanto el contexto de seguridad antiguo como el nuevo." },
  { id: 130, dom: "sec", q: "El parámetro Limit_exp del comando ADRParamSetupReq fija ADR_ACK_LIMIT como:",
    opts: ["Limit_exp directamente, en número de tramas", "2 elevado a Limit_exp", "Limit_exp multiplicado por 64", "Siempre 64, no es configurable"], a: 1, ref: "TS001-1.1 §5.11",
    exp: "Tanto ADR_ACK_LIMIT como ADR_ACK_DELAY se codifican como potencias de dos, lo que permite representar un rango amplio en un único byte." },
  { id: 131, dom: "sec", q: "El campo JoinReqType incluido en el cálculo del MIC del Join-Accept sirve para:",
    opts: ["Definir el intervalo de baliza", "Indicar el idioma del dispositivo", "Seleccionar el plan regional", "Evitar que un Join-Accept destinado a un tipo de solicitud se reutilice como respuesta a otra"], a: 3, ref: "TS001-1.1 §6.2.3",
    exp: "Al incluir el tipo de solicitud en el cálculo del MIC, un Join-Accept válido para un Rejoin-Request tipo 1 no sirve como respuesta falsificada a otro tipo." },
  { id: 132, dom: "sec", q: "¿Qué valor de JoinReqType corresponde a un Join-Request original, no a un rejoin?",
    opts: ["0x00", "0xFF", "0x01", "0x02"], a: 1, ref: "TS001-1.1 §6.2.3",
    exp: "0x00, 0x01 y 0x02 identifican, respectivamente, los Rejoin-Request tipo 0, 1 y 2; 0xFF queda reservado al Join-Request original." },
  { id: 133, dom: "sec", q: "Cuando un Join-Accept responde a un Rejoin-Request (tipo 0, 1 o 2), ¿con qué clave se cifra?",
    opts: ["Con NwkKey, igual que un Join-Request normal", "Con JSEncKey", "Con AppSKey", "No se cifra"], a: 1, ref: "TS001-1.1 §6.2.3",
    exp: "Solo el Join-Accept que responde a un Join-Request original usa NwkKey; cualquier rejoin dispara el uso de JSEncKey." },
  { id: 134, dom: "sec", q: "¿Qué claves de sesión se regeneran cuando un Rejoin-Request tipo 2 tiene éxito?",
    opts: ["Ninguna, tipo 2 no cambia nada", "Las cuatro claves de sesión, aunque los parámetros de radio no cambien", "Solo la AppSKey", "Solo las claves de red"], a: 1, ref: "TS001-1.1 §6.2.4",
    exp: "El tipo 2 está pensado justamente para renovar claves (rekeying), aunque mantenga la configuración de radio tal cual estaba." },
  { id: 135, dom: "sec", q: "Si el CFList está presente tras un Rejoin-Request tipo 2, ¿qué ocurre con los canales del dispositivo?",
    opts: ["Se ignoran, el tipo 2 nunca cambia canales", "El CFList sobrescribe los canales actuales; si está ausente, se mantienen sin cambios", "Se revierte siempre a los canales por defecto", "Se duplican los canales existentes"], a: 1, ref: "TS001-1.1 §6.2.3",
    exp: "Es distinto del comportamiento tras un Join-Request o un rejoin tipo 0/1, donde la ausencia de CFList sí implica volver a los canales por defecto." },
  { id: 136, dom: "sec", q: "¿Qué elemento no forma parte del Join-Accept según la especificación 1.1?",
    opts: ["El Home_NetID", "El JoinNonce", "El DevEUI del dispositivo", "El DLSettings"], a: 2, ref: "TS001-1.1 §6.2.3",
    exp: "El DevEUI no viaja en el Join-Accept: el servidor ya lo conoce porque llegó en el Join-Request o el rejoin que originó la respuesta." },
  { id: 137, dom: "sec", q: "El campo RxDelay del Join-Accept sigue el mismo convenio de codificación que:",
    opts: ["El CFListType", "El campo FOpts", "El NetID", "El campo Delay del comando RXTimingSetupReq"], a: 3, ref: "TS001-1.1 §6.2.3",
    exp: "Reutilizar la misma codificación simplifica la implementación: ambos campos expresan el mismo tipo de retardo entre TX y RX." },
  { id: 138, dom: "sec", q: "¿Qué longitud puede tener el Join-Accept cifrado según si incluye CFList?",
    opts: ["Siempre 16 bytes", "16 bytes sin CFList, o 32 bytes con CFList", "Siempre 32 bytes", "Variable sin límite"], a: 1, ref: "TS001-1.1 §6.2.3",
    exp: "El cifrado AES trabaja en bloques de 16 bytes, así que añadir la CFList de 16 bytes duplica exactamente el tamaño cifrado." },
  { id: 139, dom: "sec", q: "En el árbol de derivación de claves de LoRaWAN 1.0, ¿cuántas claves de sesión distintas se derivan (frente a las cuatro de 1.1)?",
    opts: ["Cuatro, igual que en 1.1", "Una única clave para todo", "Dos: NwkSKey y AppSKey", "Tres"], a: 2, ref: "TS001-1.1 §6.2.3",
    exp: "1.1 añade la separación de la integridad de red en dos mitades (FNwkSIntKey/SNwkSIntKey) y una clave de cifrado de comandos MAC (NwkSEncKey), pensadas para el roaming." },
  { id: 140, dom: "sec", q: "¿Qué garantiza que un Rejoin-Request tipo 1 no pueda reproducirse en un ataque de repetición?",
    opts: ["El Sync Word", "El cifrado del mensaje completo", "El contador RJcount1, que el Join Server nunca acepta si es menor o igual al último visto", "El límite de ciclo de trabajo"], a: 2, ref: "TS001-1.1 §6.2.4.2",
    exp: "RJcount1 es un contador propio, distinto de RJcount0, y nunca puede dar la vuelta durante la vida útil del dispositivo." },
  { id: 141, dom: "sec", q: "¿Con qué frecuencia se recomienda transmitir un Rejoin-Request tipo 1?",
    opts: ["Nunca, solo bajo demanda del servidor", "Cada segundo", "Una vez por hora obligatoriamente", "Al menos una vez al mes"], a: 3, ref: "TS001-1.1 §6.2.4.2",
    exp: "Es un mecanismo de recuperación de bajo tráfico: sirve para restaurar la sesión si el servidor la pierde por completo, no para mantenimiento rutinario." },
  { id: 142, dom: "sec", q: "¿Qué duty cycle máximo se recomienda para transmitir Rejoin-Request tipo 0 o 2?",
    opts: ["Sin límite especial", "Siempre por debajo del 0,1 %", "Un máximo de una vez por segundo", "El mismo 1 % que el resto del tráfico"], a: 1, ref: "TS001-1.1 §6.2.4",
    exp: "Al margen del límite regulatorio de la subbanda, la propia especificación acota el uso de estos rejoin para no saturar la red." },
  { id: 143, dom: "sec", q: "¿Qué ocurre con el contexto de seguridad antiguo cuando el servidor procesa un Rejoin-Request y genera un nuevo Join-Accept?",
    opts: ["Se descarta de inmediato", "Se mantiene junto al nuevo hasta recibir el primer uplink exitoso con el nuevo contexto", "Se fusiona con el nuevo", "Se reenvía de vuelta al dispositivo"], a: 1, ref: "TS001-1.1 §6.2.4",
    exp: "Es la misma cautela que se aplica a un Join-Request normal: no se abandona el contexto anterior hasta confirmar que el nuevo funciona." },
  { id: 144, dom: "sec", q: "En LoRaWAN 1.1, si un dispositivo se une a un Network Server que solo soporta 1.0, ¿qué ocurre con sus claves?",
    opts: ["La unión falla siempre", "El OptNeg queda a 0 y el dispositivo deriva las claves como en 1.0, igualando FNwkSIntKey, SNwkSIntKey y NwkSEncKey", "El dispositivo fuerza igualmente el modo 1.1", "Se pierde la AppSKey"], a: 1, ref: "TS001-1.1 §6.2.3",
    exp: "Es el mecanismo de compatibilidad hacia atrás que permite a un dispositivo 1.1 funcionar sin cambios en una red que todavía no ha migrado." },

  // --- MAC (ampliación) ---
  { id: 145, dom: "mac", q: "¿Qué bit del FCtrl de un downlink indica que el servidor tiene más datos en cola?",
    opts: ["ADR", "ACK", "FPending", "ClassB"], a: 2, ref: "TS001 §4.3.1",
    exp: "FPending solo tiene sentido en downlink; en uplink esa misma posición del FCtrl se usa para otros bits, como ADRACKReq." },
  { id: 146, dom: "mac", q: "El bit ADRACKReq en un uplink sirve para que el nodo:",
    opts: ["Indique que hay comandos MAC en FOpts", "Solicite cambiar de clase", "Pida un Rejoin-Request", "Pida al servidor que confirme que sigue oyéndolo, dentro del mecanismo de ADR"], a: 3, ref: "TS001 §5.2",
    exp: "Es la señal que dispara el backoff de ADR si el servidor no responde: el nodo empieza a sospechar que ha perdido cobertura." },
  { id: 147, dom: "mac", q: "¿Cuántos bits ocupa el subcampo FOptsLen dentro del FCtrl?",
    opts: ["2 bits", "4 bits", "8 bits", "6 bits"], a: 1, ref: "TS001 §4.3.1",
    exp: "4 bits alcanzan justo para codificar de 0 a 15, el máximo de bytes que puede llevar FOpts." },
  { id: 148, dom: "mac", q: "El MHDR de 1 byte se compone de:",
    opts: ["DevAddr y FCtrl", "Solo el MType", "MType (3 bits), RFU (3 bits) y Major (2 bits)", "FPort y FOpts"], a: 2, ref: "TS001 §4.2",
    exp: "Los 3 bits RFU quedan reservados para uso futuro; hoy no distinguen ningún comportamiento en las tramas." },
  { id: 149, dom: "mac", q: "¿Qué valor de Major identifica la versión actual de la trama LoRaWAN (R1)?",
    opts: ["00", "11", "01", "10"], a: 0, ref: "TS001 §4.2.2",
    exp: "El campo Major solo tiene 2 bits, pero hasta ahora todas las versiones publicadas de LoRaWAN usan el mismo valor, 00." },
  { id: 150, dom: "mac", q: "El bloque B0 usado en el cálculo del MIC de uplink incluye:",
    opts: ["Solo la DevAddr", "Un byte de dirección (Dir), la DevAddr, el FCntUp y la longitud del mensaje", "La AppKey en claro", "El NetID"], a: 1, ref: "TS001 §4.4",
    exp: "Construir el bloque con estos campos evita que un atacante pueda reutilizar un MIC válido cambiando el contador o el sentido de la trama." },
  { id: 151, dom: "mac", q: "El campo Dir del bloque de cifrado y del MIC indica:",
    opts: ["El sentido de la trama, 0 para uplink y 1 para downlink", "La dirección de la antena", "El sentido del roaming", "Si el dispositivo es fijo o móvil"], a: 0, ref: "TS001 §4.3.3",
    exp: "Incluir Dir en el bloque impide que una trama de uplink capturada se reutilice, con el mismo contador, como si fuera un downlink válido." },
  { id: 152, dom: "mac", q: "El valor de FType '111' (Proprietary) en el MHDR está reservado para:",
    opts: ["Uso propietario fuera del estándar LoRaWAN", "El Join-Accept", "Comandos MAC extendidos", "Tráfico multicast"], a: 0, ref: "TS001 §4.2.1",
    exp: "Permite a un fabricante definir su propio formato de trama por encima del mismo PHY, sin interferir con el resto de tipos normalizados." },
  { id: 153, dom: "mac", q: "¿Qué campo NO forma parte del FHDR de una trama LoRaWAN?",
    opts: ["El FPort", "El DevAddr", "El FCtrl", "El FCnt"], a: 0, ref: "TS001 §4.3.1",
    exp: "El FPort va después del FHDR, como campo independiente del MACPayload, no como parte de la cabecera de trama." },
  { id: 154, dom: "mac", q: "En el bloque Ai usado para cifrar el FRMPayload, ¿qué papel cumple el contador de bloque i?",
    opts: ["Genera un flujo de claves distinto para cada bloque de 16 bytes mediante AES en modo contador", "Numera los paquetes en el aire", "Determina el spreading factor", "Solo se usa al cifrar el Join-Accept"], a: 0, ref: "TS001 §4.3.3",
    exp: "Es lo que convierte AES en un cifrado de flujo: cada bloque de payload se combina por XOR con un Ai distinto, generado a partir del contador." },
  { id: 155, dom: "mac", q: "¿Qué diferencia hay en el cálculo del MIC de downlink respecto al de uplink en LoRaWAN 1.1?",
    opts: ["Ninguna, se usa la misma clave y el mismo bloque", "El downlink usa un único bloque B0 con SNwkSIntKey; el uplink combina el cmac de dos claves distintas", "El downlink no lleva MIC", "El downlink usa la AppSKey para el MIC"], a: 1, ref: "TS001-1.1 §4.4",
    exp: "Repartir el MIC de uplink entre FNwkSIntKey y SNwkSIntKey es lo que permite verificaciones parciales en escenarios de roaming; el downlink no lo necesita." },
  { id: 156, dom: "mac", q: "¿Con qué clave se cifra el FRMPayload cuando FPort = 0 en un Network Server LoRaWAN 1.1?",
    opts: ["Con la AppSKey", "Con la NwkSEncKey", "Con la NwkKey directamente", "No se cifra, va en claro"], a: 1, ref: "TS001-1.1 §6.1.2.4",
    exp: "En 1.0.x esa misma función la cumple la NwkSKey; en 1.1 se especializa en la NwkSEncKey, separada de las claves de integridad." },

  // --- CMD (ampliación) ---
  { id: 157, dom: "cmd", q: "El comando RXParamSetupAns confirma por separado la aceptación de:",
    opts: ["RX1DROffset, RX2 data rate y canal de RX2", "Potencia, data rate y canal de uplink", "ADR, ciclo de trabajo y clase", "FOpts, FPort y FCnt"], a: 0, ref: "TS001 §5.4",
    exp: "Al confirmar cada parámetro por separado, el servidor sabe exactamente cuál de los tres no pudo aplicar el dispositivo." },
  { id: 158, dom: "cmd", q: "El comando NewChannelAns confirma por separado:",
    opts: ["Si se aceptó el rango de data rate y si se aceptó la frecuencia del canal", "Solo si el canal se creó", "El número total de canales disponibles", "La potencia máxima permitida"], a: 0, ref: "TS001 §5.6",
    exp: "Igual que otros comandos de configuración, separa la confirmación de cada campo para diagnosticar mejor un rechazo parcial." },
  { id: 159, dom: "cmd", q: "TxParamSetupReq permite al servidor ajustar:",
    opts: ["El EIRP máximo y el dwell time máximo del dispositivo, en regiones que lo requieren", "El canal de RX2", "El periodo de baliza", "El número de reintentos de join"], a: 0, ref: "TS001 §5.8",
    exp: "Solo es relevante en regiones donde la regulación limita el EIRP o impone un dwell time máximo, como ocurre en algunos grupos de AS923." },
  { id: 160, dom: "cmd", q: "El comando PingSlotInfoReq permite a un dispositivo de clase B:",
    opts: ["Informar al servidor de su periodicidad de ping slot deseada", "Solicitar el periodo de baliza", "Cambiar de canal de uplink", "Pedir un Rejoin-Request"], a: 0, ref: "TS001 §12.1",
    exp: "Es el dispositivo quien decide cuántos ping slots quiere abrir por periodo de baliza, dentro de los límites del sistema." },
  { id: 161, dom: "cmd", q: "El comando BeaconFreqReq sirve para:",
    opts: ["Cambiar la frecuencia en la que el dispositivo espera la baliza", "Solicitar la hora de red", "Ajustar el ciclo de trabajo", "Confirmar el Join-Accept"], a: 0, ref: "TS001 §12.2",
    exp: "Es útil en planes de canal con salto de frecuencia de baliza, para realinear al dispositivo si ha perdido la sincronía." },
  { id: 162, dom: "cmd", q: "RejoinParamSetupReq permite al servidor:",
    opts: ["Configurar la periodicidad con la que el dispositivo transmite Rejoin-Request tipo 0 de forma automática", "Forzar un rejoin inmediato", "Cambiar el DevEUI", "Definir el número de reintentos de ADR"], a: 0, ref: "TS001-1.1 §5.14",
    exp: "Es la vía habitual para programar rejoins periódicos; ForceRejoinReq, en cambio, dispara uno inmediato bajo demanda." },
  { id: 163, dom: "cmd", q: "El comando LinkADRAns confirma tres aspectos por separado:",
    opts: ["Data rate, potencia y canal de RX2", "Potencia, data rate y máscara de canales", "FOpts, FPort y FCnt", "Clase, banda y sync word"], a: 1, ref: "TS001 §5.2",
    exp: "Si cualquiera de los tres se rechaza, el dispositivo no aplica ninguno de los cambios propuestos: LinkADRReq se trata como un todo." },
  { id: 164, dom: "cmd", q: "¿Qué comando MAC tiene el CID 0x03?",
    opts: ["DutyCycleReq", "LinkADRReq", "RXParamSetupReq", "DevStatusReq"], a: 1, ref: "TS001 §5.2",
    exp: "Los CID bajos (0x02 a 0x0A en 1.0.x) corresponden a los comandos definidos desde la primera versión de la especificación." },
  { id: 165, dom: "cmd", q: "¿Qué comando MAC corresponde al CID 0x06?",
    opts: ["NewChannelReq", "DevStatusReq", "RXParamSetupReq", "DlChannelReq"], a: 1, ref: "TS001 §5.5",
    exp: "DevStatusReq lo inicia siempre el servidor para conocer el estado de batería y el SNR del dispositivo." },
  { id: 166, dom: "cmd", q: "¿Qué CID identifica a DlChannelReq?",
    opts: ["0x07", "0x08", "0x0A", "0x0D"], a: 2, ref: "TS001 §5.6",
    exp: "DlChannelReq comparte propósito con NewChannelReq (0x07) pero se limita a modificar la frecuencia de downlink de un canal ya existente." },
  { id: 167, dom: "cmd", q: "DeviceTimeReq utiliza el CID:",
    opts: ["0x0A", "0x0B", "0x0C", "0x0D"], a: 3, ref: "TS001 §5.9",
    exp: "Es de los comandos más recientes de la serie base, introducido en LoRaWAN 1.0.3." },
  { id: 168, dom: "cmd", q: "¿Qué ventaja tiene fijar NbTrans > 1 en un enlace muy marginal?",
    opts: ["Aumenta la probabilidad de que al menos una repetición llegue, a costa de más tiempo en aire y consumo", "Reduce el consumo del nodo", "Elimina la necesidad de ADR", "Aumenta el ciclo de trabajo disponible"], a: 0, ref: "TS001 §5.2",
    exp: "Es una herramienta de compromiso: mejora la fiabilidad en el peor caso, pero multiplica la ocupación de espectro y la energía por mensaje." },
  { id: 169, dom: "cmd", q: "¿Qué mecanismo usa el Network Server para saber si un dispositivo sigue en cobertura antes de que el enlace falle del todo?",
    opts: ["El histórico de LinkCheckReq y el margen de demodulación reportado", "El Rejoin-Request tipo 1", "El límite de ciclo de trabajo", "El Sync Word"], a: 0, ref: "TS001 §5.1",
    exp: "LinkCheckAns da una foto puntual del margen y del número de gateways que oyen al dispositivo, útil como indicador temprano." },
  { id: 170, dom: "cmd", q: "Si un dispositivo acepta el data rate pero rechaza la máscara de canales de un LinkADRReq, ¿qué aplica finalmente?",
    opts: ["Solo el data rate", "Ninguno de los tres parámetros del comando", "Todos, porque el rechazo parcial no cuenta", "Los canales por defecto de la región"], a: 1, ref: "TS001 §5.2",
    exp: "LinkADRReq se acepta o se rechaza como conjunto atómico: no hay aplicación parcial de sus tres campos." },
  { id: 171, dom: "cmd", q: "¿Qué distingue a RXTimingSetupReq de RXParamSetupReq?",
    opts: ["El primero ajusta el retardo entre el fin del uplink y RX1; el segundo ajusta frecuencia y data rate de RX1/RX2", "Son sinónimos exactos", "El primero solo aplica a clase B", "El segundo no tiene respuesta de confirmación"], a: 0, ref: "TS001 §5.4",
    exp: "Cambiar el retardo (RECEIVE_DELAY1) es una operación distinta de reconfigurar dónde y a qué data rate escucha el dispositivo." },
  { id: 172, dom: "cmd", q: "El comando DutyCycleReq puede imponer un ciclo de trabajo agregado:",
    opts: ["Menos restrictivo que el límite regulatorio de la subbanda, nunca más", "Más restrictivo que el límite regulatorio, por decisión del operador de red", "Solo aplicable a las balizas", "Solo aplicable en clase C"], a: 1, ref: "TS001 §5.3",
    exp: "Es una restricción adicional que el operador puede imponer por motivos de capacidad de red, independiente del límite legal de la banda." },

  // --- REG (ampliación) ---
  { id: 173, dom: "reg", q: "En US915, ¿qué SF y BW corresponden a DR0?",
    opts: ["SF7/125 kHz", "SF10/125 kHz", "SF12/500 kHz", "SF8/500 kHz"], a: 1, ref: "RP002 §2.5.3",
    exp: "US915 empieza en SF10 (no en SF12 como EU868) porque el dwell time de 400 ms hace impracticables los spreading factors más altos en 125 kHz." },
  { id: 174, dom: "reg", q: "En US915, ¿a qué configuración corresponde DR4?",
    opts: ["SF8/500 kHz", "SF7/125 kHz", "SF12/500 kHz", "LR-FHSS"], a: 0, ref: "RP002 §2.5.3",
    exp: "DR4 usa 500 kHz de ancho de banda, lo que reduce el tiempo en aire lo suficiente como para no chocar con el límite de dwell time." },
  { id: 175, dom: "reg", q: "En US915, los data rates DR8 a DR13 se usan exclusivamente para:",
    opts: ["Uplink de emergencia", "Downlink, con SF12 a SF7 sobre 500 kHz", "El Join-Request", "Las balizas de clase B"], a: 1, ref: "RP002 §2.5.3",
    exp: "El downlink de US915 vive en su propio rango de data rates y de canales, separado por completo del uplink." },
  { id: 176, dom: "reg", q: "¿Cómo se determina el canal de RX1 a partir del canal de uplink en US915?",
    opts: ["Siempre es el canal 0", "Canal de uplink módulo 8", "Se elige al azar", "Es igual al canal de uplink"], a: 1, ref: "RP002 §2.5.7",
    exp: "Con 64 canales de uplink y solo 8 de downlink, la regla módulo 8 reparte de forma determinista qué canal de RX1 corresponde a cada uno." },
  { id: 177, dom: "reg", q: "¿Qué rango de valores admite RX1DROffset en US915?",
    opts: ["0 a 3", "0 a 7", "0 a 15", "Solo 0"], a: 0, ref: "RP002 §2.5.7",
    exp: "Los valores 4 a 7 quedan reservados para uso futuro, a diferencia de otras regiones con rangos distintos." },
  { id: 178, dom: "reg", q: "En US915, ¿a qué corresponden los data rates DR5 y DR6?",
    opts: ["LR-FHSS a 1,523 MHz de ancho de banda (CR 1/3 y 2/3)", "SF7 y SF8 a 500 kHz", "Canales exclusivos de downlink", "Data rates reservados sin uso"], a: 0, ref: "RP002 §2.5.3",
    exp: "LR-FHSS comparte los mismos 8 canales de 500 kHz que DR4, pero con una modulación completamente distinta." },
  { id: 179, dom: "reg", q: "¿Cuántos canales de baliza de clase B define US915 y en qué rango?",
    opts: ["8, de 923,3 a 927,5 MHz cada 600 kHz", "1 único canal fijo", "64, los mismos que el uplink", "16 canales"], a: 0, ref: "RP002 §2.5.8",
    exp: "Coincide con los 8 canales de downlink de datos: la baliza rota entre ellos según el número de baliza." },
  { id: 180, dom: "reg", q: "Un dispositivo US915 personalizado (ABP) recién reiniciado tiene habilitados:",
    opts: ["Solo los 8 primeros canales", "Los 72 canales", "Ninguno, hasta recibir NewChannelReq", "Solo los 64 de 125 kHz"], a: 1, ref: "RP002 §2.5.2",
    exp: "Sin Join-Accept que restrinja la lista, un dispositivo ABP arranca con toda la estructura de 72 canales activa." },
  { id: 181, dom: "reg", q: "¿Qué modo de transmisión de la normativa FCC permite hasta +30 dBm en US915 con salto de frecuencia?",
    opts: ["DTS (Digital Transmission System)", "FHSS (Frequency-Hopping Spread Spectrum)", "Modo híbrido", "LBT"], a: 1, ref: "RP002 §2.5.2",
    exp: "A cambio de esa potencia, el modo FHSS exige saltar entre al menos 50 canales y respetar el dwell time de 400 ms." },
  { id: 182, dom: "reg", q: "¿Cuántos canales de downlink dedicados define US915 y en qué rango de frecuencia?",
    opts: ["8 canales, de 923,3 a 927,5 MHz", "64 canales, de 902 a 915 MHz", "16 canales, en 869 MHz", "No hay canales dedicados de downlink"], a: 0, ref: "RP002 §2.5.2",
    exp: "A diferencia de EU868, donde el downlink reutiliza los canales de uplink, US915 separa por completo ambos sentidos." },
  { id: 183, dom: "reg", q: "AU915 comparte una estructura de canales similar a la de:",
    opts: ["EU868", "US915, con 64+8 canales y un offset de frecuencia propio", "AS923", "CN470"], a: 1, ref: "RP002 §2.8",
    exp: "Ambas regiones nacieron de la misma filosofía de canal fijo con conjunto amplio de frecuencias, adaptada a cada regulación local." },
  { id: 184, dom: "reg", q: "IN865 se caracteriza frente a otras regiones por:",
    opts: ["No tener un límite de ciclo de trabajo estricto, con solo tres canales por defecto", "Exigir LBT de forma obligatoria", "Definir 96 canales", "Prohibir el uso de OTAA"], a: 0, ref: "RP002 §2.12",
    exp: "Su regulación es más permisiva que la europea en cuanto a ciclo de trabajo, aunque el plan de canales por defecto es reducido." },
  { id: 185, dom: "reg", q: "CN470 destaca frente al resto de regiones por:",
    opts: ["Definir hasta 96 canales, con planes de downlink específicos según el tipo de antena", "No admitir clase B", "Ser idéntica a EU868", "Usar únicamente 500 kHz de ancho de banda"], a: 0, ref: "RP002 §2.9",
    exp: "Es la región con más canales de todas las que cubre RP002, pensada para el mercado chino y sus propias restricciones de banda." },
  { id: 186, dom: "reg", q: "RU864 se parece estructuralmente a:",
    opts: ["EU868, con la banda desplazada", "US915", "AS923", "KR920"], a: 0, ref: "RP002 §2.13",
    exp: "Comparte filosofía de plan de canales con EU868, adaptada a la asignación de espectro disponible en Rusia." },
  { id: 187, dom: "reg", q: "Según el historial de revisiones de RP002, ¿qué cambió para AS923 en la Data Rate 2 respecto al tamaño máximo de payload?",
    opts: ["Se redujo por restricciones de dwell time", "Se incrementó respecto a versiones anteriores de la especificación", "Se eliminó ese data rate", "No ha cambiado nunca"], a: 1, ref: "RP002 §5.3",
    exp: "Es uno de los ajustes documentados en las notas de revisión de RP002-1.0.1, que alineó ese valor con el resto de regiones equivalentes." },
  { id: 188, dom: "reg", q: "AS923-4 se añadió en una revisión de RP002 para cubrir:",
    opts: ["917-920 MHz, dando cobertura a Israel", "Un nuevo país europeo", "La banda de 2,4 GHz", "Corea del Sur"], a: 0, ref: "RP002 §5.1",
    exp: "Es un ejemplo de cómo el plan base de AS923 se extiende con nuevos grupos de desplazamiento a medida que se suman países." },
  { id: 189, dom: "reg", q: "EU433 se diferencia de EU868 principalmente en:",
    opts: ["Solo en la banda de frecuencia; el resto del plan sigue una filosofía muy similar", "En que no admite clase B", "En que no tiene límite de ciclo de trabajo", "En que exige LBT"], a: 0, ref: "RP002 §2.7",
    exp: "EU433 reutiliza la misma lógica regulatoria europea de ciclo de trabajo por subbanda, solo que desplazada a la banda de 433 MHz." },
  { id: 190, dom: "reg", q: "CN779-787 es una región definida en RP002 pensada para:",
    opts: ["Un uso residual en 779-787 MHz con un plan de canales similar al europeo", "Sustituir a CN470 en todo el país", "Dispositivos de clase C exclusivamente", "Comunicación por satélite"], a: 0, ref: "RP002 §2.6",
    exp: "Es una de las regiones menos usadas del documento, con un plan de canales y restricciones muy parecidas a las de EU868/EU433." },

  // --- OPS (ampliación) ---
  { id: 191, dom: "ops", q: "¿Qué mide el 'presupuesto de enlace' (link budget) de un despliegue LoRaWAN?",
    opts: ["La diferencia entre la potencia transmitida y la sensibilidad del receptor, menos las pérdidas del camino", "El número de dispositivos soportados por celda", "El ciclo de trabajo disponible", "El consumo total de batería de la red"], a: 0,
    exp: "Es el cálculo base para saber si un enlace concreto va a funcionar antes de desplegar nada sobre el terreno." },
  { id: 192, dom: "ops", q: "Un aumento sostenido del SNR medio reportado por LinkCheckAns en toda una celda sugiere:",
    opts: ["Más interferencia en la banda", "Mejores condiciones de propagación o nodos más próximos a los gateways", "Que el ciclo de trabajo se ha agotado", "Un aumento de las colisiones"], a: 1,
    exp: "El SNR es una medida de la calidad del enlace recibido; su mejora generalizada apunta a causas de propagación, no de congestión." },
  { id: 193, dom: "ops", q: "¿Por qué no tiene sentido aplicar ADR durante el propio proceso de unión (Join)?",
    opts: ["Porque el Join-Request se transmite con un data rate elegido por el nodo, sin retroalimentación previa del servidor", "Porque el Join Server lo bloquea explícitamente", "Porque el ADR solo aplica a dispositivos de clase C", "Porque el Join-Request no tiene FCtrl"], a: 0, ref: "TS001 §6.2.5",
    exp: "El ADR necesita un historial de tramas ya intercambiadas con el servidor, que todavía no existe antes de completar la unión." },
  { id: 194, dom: "ops", q: "¿Qué ventaja aporta desplegar varios gateways superpuestos en una misma zona?",
    opts: ["Diversidad de recepción: mayor probabilidad de que al menos uno reciba cada uplink", "Duplica el ciclo de trabajo disponible", "Permite mayor potencia de transmisión", "Elimina la necesidad de usar ADR"], a: 0,
    exp: "Es la estrategia habitual para mejorar la fiabilidad sin subir potencia ni spreading factor, aunque no evita el límite de ciclo de trabajo del downlink." },
  { id: 195, dom: "ops", q: "Al planificar la capacidad de una red, ¿qué combinación resulta más limitante para el downlink?",
    opts: ["Muchos joins simultáneos con tramas confirmadas y spreading factors altos", "Pocos dispositivos en SF7", "Uplinks no confirmados en clase A", "Dispositivos operando en modo ABP"], a: 0,
    exp: "Cada confirmación y cada Join-Accept consumen presupuesto de downlink del gateway, que ya de por sí es el recurso más escaso." },
  { id: 196, dom: "ops", q: "¿Qué papel juega el margen de desvanecimiento (fade margin) en un cálculo de enlace?",
    opts: ["Compensa la variabilidad de la propagación real frente al modelo teórico", "Sustituye al cálculo de sensibilidad", "Determina el ciclo de trabajo permitido", "Reemplaza a la ganancia de antena"], a: 0,
    exp: "Sin ese margen, un enlace que funciona en el papel puede fallar de forma intermitente por lluvia, vegetación o simple variabilidad del entorno." },
  { id: 197, dom: "ops", q: "Al migrar dispositivos de ABP a OTAA, ¿qué riesgo conviene gestionar primero?",
    opts: ["Ninguno, la migración es transparente", "Coordinar la retirada de contadores y claves antiguas para evitar colisiones de sesión", "El cambio de banda de frecuencia", "La pérdida del DevEUI"], a: 1,
    exp: "Dejar convivir la sesión ABP antigua con una nueva sesión OTAA sin desactivar la primera puede generar conflictos de DevAddr o de contador." },
  { id: 198, dom: "ops", q: "¿Qué indica un aumento sostenido del número de Rejoin-Request tipo 1 en una red?",
    opts: ["Pérdida de estado de sesión en el Network Server con cierta frecuencia", "Un ataque de repetición exitoso", "Un fallo en la capa física", "Un cambio de clase masivo de los dispositivos"], a: 0, ref: "TS002 §15",
    exp: "El tipo 1 existe precisamente para ese escenario de recuperación; verlo con frecuencia alta es señal de un problema de estabilidad en el servidor." },
  { id: 199, dom: "ops", q: "¿Por qué es relevante revisar la gestión de DevNonce en dispositivos ABP heredados durante una auditoría de seguridad?",
    opts: ["Porque ABP no usa DevNonce ni Join-Request, así que lo relevante es la persistencia del FCnt, no del DevNonce", "Porque ABP también genera un DevNonce por sesión", "Porque el DevNonce protege el FRMPayload", "Porque el DevNonce sustituye a la AppSKey"], a: 0, ref: "TS001 §6.3",
    exp: "Confundir los mecanismos de protección de OTAA y ABP es un error común: en ABP el punto crítico es la persistencia de los contadores de trama." },
  { id: 200, dom: "ops", q: "¿Qué mecanismo de LoRaWAN reduce el impacto de un ataque de repetición contra el Join-Request?",
    opts: ["El Sync Word", "El DevNonce, un contador monótono verificado por el servidor", "El límite de ciclo de trabajo", "El CRC de capa física"], a: 1, ref: "TS001 §6.2.5",
    exp: "Un DevNonce ya usado o inferior al último visto hace que el servidor descarte el Join-Request, aunque el resto del mensaje sea válido." },
  { id: 201, dom: "ops", q: "Al dimensionar cuántos gateways necesita una celda, ¿qué recurso conviene calcular primero: capacidad de uplink o de downlink?",
    opts: ["El uplink, porque siempre es más escaso", "El downlink, porque el gateway es semidúplex y su ciclo de trabajo lo comparten todos los dispositivos de la celda", "Ninguno, ambos son ilimitados", "Depende solo del número de gateways instalados"], a: 1,
    exp: "El uplink escala con el número de dispositivos porque cada uno tiene su propio presupuesto regulatorio; el downlink lo comparten todos a través del mismo gateway, que además no puede recibir mientras transmite." },
];
